        enum class SessionPhase : std::uint8_t {
            WaitConnect = 0,
            WaitAnsCode = 1,
            Playing = 2,
        };

        class ProtocolPointDecay {
          public:
            static constexpr std::uint64_t kIntervalMs = 300000;

            void restart(SessionPhase phase, int points, std::uint64_t now) {
                m_deadline = phase == SessionPhase::Playing && points > 0 ? now + kIntervalMs : 0;
            }

            [[nodiscard]] bool due(SessionPhase phase, std::uint64_t now) const {
                return phase == SessionPhase::Playing && m_deadline != 0 && now >= m_deadline;
            }

            void advance(int points) {
                m_deadline = points > 0 ? m_deadline + kIntervalMs : 0;
            }

          private:
            std::uint64_t m_deadline = 0;
        };

        /** Checks fixed wire layouts before state-dependent gameplay handlers run. */
        [[nodiscard]] bool malformed_world_packet(protocol::C2S type,
                                                  const std::vector<std::uint8_t>& payload) {
            switch (type) {
            case protocol::C2S::Attack:
                return payload.size() != 5 ||
                       (payload[0] != protocol::kCkPlayer && payload[0] != protocol::kCkMonster);
            case protocol::C2S::MoveOn:
            case protocol::C2S::MoveEnd:
                return payload.size() != 3;
            case protocol::C2S::PreSkill:
                return payload.size() != 5;
            case protocol::C2S::Skill:
                switch (payload.size()) {
                case 1:
                    return payload[0] == 0;
                case 2:
                    return payload[0] != 0 || payload[1] > 1;
                case 6:
                case 10:
                    return payload[0] == 0 || (payload[1] != protocol::kCkPlayer &&
                                               payload[1] != protocol::kCkMonster);
                case 9:
                    return payload[0] == 0;
                default:
                    return true;
                }
            case protocol::C2S::Teleport:
                return payload.size() != 1 && (payload.size() != 5 || payload[0] > 1);
            case protocol::C2S::PickupItem:
                return payload.size() != 12;
            case protocol::C2S::SortInventory:
                return payload.size() != 1 || payload[0] > 1;
            case protocol::C2S::GameExit:
                return !payload.empty();
            default:
                return false;
            }
        }

