        class MovementBudget {
          public:
            /** Allow up to 1.5 seconds of movement to arrive in a burst. */
            static constexpr double kBurstSeconds = 1.5;
            [[nodiscard]] bool spend(double travel_seconds, std::uint64_t now) {
                m_seconds = std::min(kBurstSeconds, m_seconds + (now - m_updated_ms) / 1000.0);
                m_updated_ms = now;
                if (travel_seconds > m_seconds) {
                    return false;
                }
                m_seconds -= travel_seconds;
                return true;
            }

          private:
            double m_seconds = kBurstSeconds;
            std::uint64_t m_updated_ms = 0;
        };

