            /** The first two registers are available without an unlock. */
            static constexpr int kBaseRegisters = 2;
            /** Authoritative storage for every base and unlockable register. */
            static constexpr int kGeneralSlots =
                kSlotsPerRegister * (kBaseRegisters + InventoryUnlockSet::kMaxUnlocks);
            /** Quest Items and Task Items each have one permanently available section. */
            static constexpr int kBagSlots = kGeneralSlots + 2 * kSlotsPerRegister;
