        /** Buff/heal target that is either a live session or a debug dummy. */
        struct PlayerBuffTarget {
            /** Live session, or nullptr when this is a dummy. */
            ClientSession* session = nullptr;

            /** Debug dummy, or nullptr when this is a live session. */
            DummyPlayer* dummy = nullptr;

            /** @return True when a session or dummy is bound. */
            [[nodiscard]] bool valid() const {
                return session != nullptr || dummy != nullptr;
            }

            /** @return Entity id. */
            [[nodiscard]] std::uint32_t player_id() const {
                return session ? session->player_id : dummy->player_id();
            }

            /** @return Logical map. */
            [[nodiscard]] int map() const {
                return session ? session->map : dummy->map();
            }

            /** @return Server pixel X. */
            [[nodiscard]] int px() const {
                return session ? session->px : dummy->px();
            }

            /** @return Server pixel Y. */
            [[nodiscard]] int py() const {
                return session ? session->py : dummy->py();
            }

            /** @return Current HP. */
            [[nodiscard]] std::int32_t cur_hp() const {
                return session ? session->cur_hp : dummy->cur_hp();
            }

            /**
             * Sets current HP.
             * @param value Hit points.
             */
            void set_cur_hp(std::int32_t value) {
                if (session) {
                    session->cur_hp = value;
                } else {
                    dummy->set_cur_hp(value);
                }
            }

            /** @return Maximum HP. */
            [[nodiscard]] std::int32_t max_hp() const {
                return session ? session->max_hp : dummy->max_hp();
            }

            /** @return Current MP. */
            [[nodiscard]] std::int32_t cur_mp() const {
                return session ? session->cur_mp : dummy->cur_mp();
            }

            /**
             * Sets current MP.
             * @param value Mana.
             */
            void set_cur_mp(std::int32_t value) {
                if (session) {
                    session->cur_mp = value;
                } else {
                    dummy->set_cur_mp(value);
                }
            }

            /** @return Maximum MP. */
            [[nodiscard]] std::int32_t max_mp() const {
                return session ? session->max_mp : dummy->max_mp();
            }

            /** @return Skill buffs. */
            [[nodiscard]] SkillBuffSet& skill_buffs() {
                return session ? session->skill_buffs : dummy->skill_buffs();
            }

            /** @return True when the live session has god mode. */
            [[nodiscard]] bool godmode() const {
                return session && session->godmode;
            }

            /** @return Fatal rate for Archer curse scaling. */
            [[nodiscard]] std::int32_t fatal_rate() const {
                return session ? session->fatal_rate : dummy->fatal_rate();
            }

            /** @return Character class. */
            [[nodiscard]] int clazz() const {
                return session ? session->clazz : dummy->clazz();
            }

            /** @return Current attack range in pixels. */
            [[nodiscard]] int attack_range() const {
                return session ? session->attack_range : 16;
            }

            /** @return Mutable control-lock deadline. */
            [[nodiscard]] std::uint64_t& control_until_ms() {
                return session ? session->control_until_ms : dummy->mutable_control_until_ms();
            }

            /**
             * True when this target is the given session.
             * @param c Session to compare.
             * @return True on identity match.
             */
            [[nodiscard]] bool is_session(const ClientSession& c) const {
                return session == &c;
            }
        };

