        /** Host-side Archer dispatch family used until a cast reaches its specialized handler. */
        enum class ArcherRoute : std::uint8_t {
            Reject = 0,
            Shared,
            Damage,
            StunArrow,
            PoisonArrow,
            FocusShot,
            AggroReduction,
            LifeAbsorption,
            Pain,
            Debuff,
            SelfBuff,
            EmergencyEscape,
            PoisonCloud,
            ArrowRain,
            ArrowExplosion,
            Commonback,
        };

        /** Returns the authoritative supported route for an Archer skill index. */
        [[nodiscard]] constexpr ArcherRoute archer_route(int skill_index) {
            if (protocol::archer_is_blocked_skill(skill_index)) {
                return ArcherRoute::Reject;
            }
            switch (protocol::archer_special_kind(skill_index)) {
            case protocol::ArcherSpecialKind::Beheading:
                return ArcherRoute::Shared;
            case protocol::ArcherSpecialKind::HeartBreaker:
                return ArcherRoute::StunArrow;
            case protocol::ArcherSpecialKind::PoisonArrow:
                return ArcherRoute::PoisonArrow;
            case protocol::ArcherSpecialKind::FocusShot:
                return ArcherRoute::FocusShot;
            case protocol::ArcherSpecialKind::AggroReduction:
                return ArcherRoute::AggroReduction;
            case protocol::ArcherSpecialKind::EmergencyEscape:
                return ArcherRoute::EmergencyEscape;
            case protocol::ArcherSpecialKind::PoisonCloud:
                return ArcherRoute::PoisonCloud;
            case protocol::ArcherSpecialKind::ArrowRain:
                return ArcherRoute::ArrowRain;
            case protocol::ArcherSpecialKind::ArrowExplosion:
                return ArcherRoute::ArrowExplosion;
            case protocol::ArcherSpecialKind::Return:
                return ArcherRoute::Commonback;
            default:
                break;
            }
            switch (protocol::archer_effect_kind(skill_index)) {
            case protocol::ArcherEffectKind::Damage:
            case protocol::ArcherEffectKind::DamageControl:
                return ArcherRoute::Damage;
            case protocol::ArcherEffectKind::Drain:
                return ArcherRoute::LifeAbsorption;
            case protocol::ArcherEffectKind::Buff:
                return ArcherRoute::SelfBuff;
            case protocol::ArcherEffectKind::Debuff:
                if (skill_index == 19) {
                    return ArcherRoute::Pain;
                }
                return ArcherRoute::Debuff;
            case protocol::ArcherEffectKind::Dispel:
                return ArcherRoute::Debuff;
            default:
                return ArcherRoute::Reject;
            }
        }

