            rec.cur_end = slot.cur_end;
            rec.max_end = slot.max_end;
            rec.x_attack = slot.x_attack;
            rec.x_magic = slot.x_magic;
            rec.x_hit = slot.x_hit;
            rec.x_defense = slot.x_defense;
            rec.x_dodge = slot.x_dodge;
            rec.upgrade_level = slot.upgrade_level;
            rec.upgrade_rate = slot.upgrade_rate;
            rec.mix_type = slot.mix_type;
            rec.bof = slot.bof;
            rec.qigong_perforated = slot.qigong_perforated;
            rec.qigong_effect = slot.qigong_effect;
            rec.dragon_effect = slot.dragon_effect;
            rec.random_stat_type = slot.random_stat_type;
            rec.random_stat_value = slot.random_stat_value;
