        [[nodiscard]] ClientSession::BagSlot bag_slot_from_record(const ItemRecord& item) {
            ClientSession::BagSlot slot;
            slot.iid = static_cast<std::uint32_t>(item.iid);
            slot.index = item.index;
            slot.prefix = item.prefix;
            slot.count = item.count;
            slot.cur_end = item.cur_end;
            slot.max_end = item.max_end;
            slot.x_attack = item.x_attack;
            slot.x_magic = item.x_magic;
            slot.x_hit = item.x_hit;
            slot.x_defense = item.x_defense;
            slot.x_dodge = item.x_dodge;
            slot.upgrade_level = item.upgrade_level;
            slot.upgrade_rate = item.upgrade_rate;
            slot.mix_type = item.mix_type;
            slot.bof = item.bof;
            slot.qigong_perforated = item.qigong_perforated;
            slot.qigong_effect = item.qigong_effect;
            slot.dragon_effect = item.dragon_effect;
            slot.enchant_protected = item.enchant_protected;
            slot.random_stat_type = item.random_stat_type;
            slot.random_stat_value = item.random_stat_value;
            slot.transform_level = item.transform_level < 1 ? 1 : item.transform_level;
            slot.transform_exp = item.transform_exp < 0 ? 0 : item.transform_exp;
            slot.pet_expire_at = std::max<std::int64_t>(0, item.pet_expire_at);
            slot.ride_expire_at = std::max<std::int64_t>(0, item.ride_expire_at);
            slot.account_bound = item.account_bound;
            slot.character_bound = item.character_bound;
            return slot;
        }

        ClientSession::BagSlot trading_post_slot(const protocol::TradeItem& item) {
            using A = protocol::TradeAttribute;
            ClientSession::BagSlot slot;
            slot.iid = item.iid;
            slot.index = item.index;
            slot.count = item.count;
            slot.prefix = item.attribute(A::Prefix);
            slot.cur_end = item.attribute(A::CurrentEndurance);
            slot.max_end = item.attribute(A::MaximumEndurance);
            slot.x_attack = item.attribute(A::Attack);
            slot.x_magic = item.attribute(A::Magic);
            slot.x_hit = item.attribute(A::Hit);
            slot.x_defense = item.attribute(A::Defense);
            slot.x_dodge = item.attribute(A::Dodge);
            slot.upgrade_level = item.attribute(A::UpgradeLevel);
            slot.upgrade_rate = item.attribute(A::UpgradeRate);
            slot.mix_type = item.attribute(A::Mix);
            slot.bof = item.attribute(A::BeadOfFire);
            slot.qigong_perforated = item.attribute(A::Perforated);
            slot.qigong_effect = item.attribute(A::Qigong);
            slot.dragon_effect = item.attribute(A::Dragon);
            slot.random_stat_type = item.attribute(A::RandomType);
            slot.random_stat_value = item.attribute(A::RandomValue);
            slot.transform_level = item.attribute(A::AnimalLevel);
            slot.transform_exp = item.attribute(A::AnimalExp);
            slot.enchant_protected = item.attribute(A::Protected) != 0;
            slot.pet_expire_at = static_cast<std::int64_t>(item.pet_expire_at);
            slot.ride_expire_at = static_cast<std::int64_t>(item.ride_expire_at);
            return slot;
        }

        /** Writes worn animal EXP/level onto the equipped egg item (compatibility behavior).
         * @param store Persistence backend, or null to skip the write.
         * @param c Player whose worn transform is flushed.
         */
        void flush_worn_transform_item(IDataStore* store, ClientSession& c) {
            if (!store || c.character_id <= 0 || c.transform.index <= 0) {
                return;
            }
            for (auto& slot : c.bag) {
                if (!slot.equipped || slot.index != c.transform.index || slot.iid == 0) {
                    continue;
                }
                slot.transform_level = c.transform.level < 1 ? 1 : c.transform.level;
                slot.transform_exp = c.transform.exp < 0 ? 0 : c.transform.exp;
                ItemRecord rec;
                fill_item_record_from_slot(rec, c, slot, 3);
                (void) store->update_item(rec);
                return;
            }
        }

        bool persist_character(IDataStore* store, ClientSession& c) {
            if (!store || c.character_id <= 0) {
                return false;
            }
            flush_worn_transform_item(store, c);
            if (!store->save_character(character_from_session(c))) {
                log::error("ServerHost: failed to persist character " +
                           std::to_string(c.character_id));
                return false;
            }
            using clock = std::chrono::steady_clock;
            c.last_autosave_ms =
                static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
                                               clock::now().time_since_epoch())
                                               .count());
            return true;
        }

        /** Wall-clock unix seconds for pay-buff deadlines. */
        [[nodiscard]] std::int64_t unix_now_sec() {
            using clock = std::chrono::system_clock;
            return static_cast<std::int64_t>(
                std::chrono::duration_cast<std::chrono::seconds>(clock::now().time_since_epoch())
                    .count());
        }

        bool castle_opponents(const ClientSession& source, const ClientSession& target) {
            return source.castle_side != CastleWarSide::None &&
                   target.castle_side != CastleWarSide::None &&
                   source.castle_side != target.castle_side;
        }

        [[nodiscard]] bool assassin_safe(const ClientSession& c) {
            if (c.map == 0 && g_pvp_world->grid().has_attr_world_pixel(
                                  c.px, c.py, map::kAttrVillage | map::kAttrSafety)) {
                return true;
            }
            const auto& areas = g_pvp_config->assassin_safe_areas;
            return std::any_of(areas.begin(), areas.end(), [&](const auto& bounds) {
                return c.map == bounds[0] && c.px >= bounds[1] && c.py >= bounds[2] &&
                       c.px <= bounds[3] && c.py <= bounds[4];
            });
        }

        [[nodiscard]] bool duel_opponents(const ClientSession& a, const ClientSession& b) {
            return a.duel_peer != 0 && a.duel_peer == b.player_id && b.duel_peer == a.player_id;
        }

        bool pvp_allows_attack(const ClientSession& source, const ClientSession* target) {
            if (source.castle_side != CastleWarSide::None ||
                (target && target->castle_side != CastleWarSide::None)) {
                return g_castle_war && target && !source.tele_pending && !target->tele_pending &&
                       castle_opponents(source, *target) &&
                       g_castle_war->hostile(
                           source.character_id, target->character_id, unix_now_sec());
            }
            if (!target || !g_pvp_config || !g_pvp_config->multiplayer) {
                // Standalone sessions and debug dummies keep their existing skill behavior.
                return true;
            }
            if (&source == target || source.cur_hp <= 0 || target->cur_hp <= 0 ||
                source.duel_recovery_at_ms != 0 || target->duel_recovery_at_ms != 0 ||
                source.map != target->map || source.tele_pending || target->tele_pending) {
                return false;
            }
            if (duel_opponents(source, *target)) {
                return true;
            }
            return (is_assassin(source) || is_assassin(*target)) && !assassin_safe(source) &&
                   !assassin_safe(*target);
        }

        bool pvp_allows_support(const ClientSession& source, const ClientSession* target) {
            if (source.castle_side != CastleWarSide::None ||
                (target && target->castle_side != CastleWarSide::None)) {
                return target && source.castle_side != CastleWarSide::None &&
                       source.castle_side == target->castle_side;
            }
            return !target || (!duel_opponents(source, *target) &&
                               is_assassin(source) == is_assassin(*target));
        }

        bool castle_spawn_protected(const ClientSession& session) {
            if (session.castle_side == CastleWarSide::None) {
                return false;
            }
            const auto entry = g_castle_war->participant(session.character_id);
            return entry && unix_now_sec() < entry->protected_until;
        }

        std::int32_t castle_pvp_damage(const ClientSession& source,
                                       const ClientSession* target,
                                       std::int32_t damage) {
            if (damage <= 0 || !target || !castle_opponents(source, *target)) {
                return damage;
            }
            const auto now = unix_now_sec();
            const int attack = g_castle_war->pvp_bonus(source.character_id, now).first;
            const int defense = g_castle_war->pvp_bonus(target->character_id, now).second;
            return combat::clamp_nonneg_i32(static_cast<std::int64_t>(damage) *
                                            (100 + attack - defense) / 100);
        }

        std::uint64_t steady_ms_now();

        void record_pvp_hit(const ClientSession& source,
                            ClientSession* target,
                            bool skill,
                            bool score_death = true) {
            if (!target) {
                return;
            }
            if (!castle_opponents(source, *target)) {
                if (score_death && target->cur_hp <= 0) {
                    if (duel_opponents(source, *target)) {
                        target->duel_recovery_at_ms = steady_ms_now() + kDuelRecoveryDelayMs;
                    } else if (is_assassin(*target)) {
                        target->pvp_death_exp_percent = kAssassinExpPercent;
                        target->pvp_death_unsaved = true;
                        target->assassin_last_hitter = source.name;
                    } else if (is_assassin(source)) {
                        target->pvp_death_exp_percent = kAssassinVictimExpPercent;
                        target->pvp_death_unsaved = true;
                    }
                }
                return;
            }
            const auto now = unix_now_sec();
            if (skill) {
                (void) g_castle_war->record_activity(
                    source.character_id, CastleWarActivity::Skill, now);
            }
            if (score_death && target->cur_hp <= 0) {
                (void) g_castle_war->record_kill(source.character_id, target->character_id, now);
            }
        }

        void castle_score_support(const ClientSession& source, const ClientSession* target) {
            if (g_castle_war && target && &source != target &&
                source.castle_side != CastleWarSide::None) {
                (void) g_castle_war->record_activity(
                    source.character_id, CastleWarActivity::Support, unix_now_sec());
            }
        }

        std::int64_t castle_merchant_price(std::int64_t base, int npc_index) {
            if (!g_castle_war) {
                return base;
            }
            const auto& merchants = g_castle_war->rules().merchant_npc_indices;
            if (std::find(merchants.begin(), merchants.end(), npc_index) == merchants.end()) {
                return base;
            }
            return std::clamp<std::int64_t>(base * g_castle_war->tax_percent() / 100,
                                            1,
                                            std::numeric_limits<std::uint32_t>::max());
        }

        /** Persists active pay buffs (S2D_BUFFREMAIN). */
        bool persist_pay_buffs(IDataStore* store, ClientSession& c) {
            if (!store || c.character_id <= 0) {
                return false;
            }
            if (!store->replace_buff_remains(
                    c.character_id, c.pay_buffs.snapshot(c.character_id, unix_now_sec()))) {
                log::error("ServerHost: failed to persist buffs for character " +
                           std::to_string(c.character_id));
                return false;
            }
            return true;
        }

        /** Persists active inventory-register unlocks. */
        bool persist_inventory_unlocks(IDataStore* store, ClientSession& c) {
            if (!store || c.character_id <= 0) {
                return false;
            }
            if (!store->replace_inventory_unlocks(
                    c.character_id, c.inventory_unlocks.snapshot(c.character_id, unix_now_sec()))) {
                log::error("ServerHost: failed to persist inventory unlocks for character " +
                           std::to_string(c.character_id));
                return false;
            }
            return true;
        }

        /** Sends a single-word property update to the owning client. */
        void send_cur_property(ClientSession& c, protocol::PropertyType type, std::int32_t value);
        CollectionItem collection_item(const ClientSession::BagSlot& slot) {
            return {slot.iid,
                    slot.index,
                    slot.upgrade_level,
                    slot.random_stat_type,
                    slot.random_stat_value,
                    slot.mix_type,
                    slot.equipped};
        }

        std::vector<CollectionItem> collection_items(const ClientSession& c) {
            std::vector<CollectionItem> items;
            for (const auto& slot : c.bag) {
                if (slot.count > 0 && collection_def(slot.index).kind != CollectionKind::None) {
                    items.push_back(collection_item(slot));
                }
            }
            for (const auto& slot : c.collection) {
                if (slot.count > 0) {
                    items.push_back(collection_item(slot));
                }
            }
            return items;
        }

        void roll_collection_option(ClientSession::BagSlot& slot) {
            const auto def = collection_def(slot.index);
            if (def.kind == CollectionKind::Taegeuk) {
                const int types[] = {107, 106, 105};
                const int values[][3] = {{4, 1, 1}, {10, 2, 2}, {25, 4, 4}};
                const int choice = combat::irand(0, 2);
                slot.random_stat_type = types[choice];
                slot.random_stat_value = values[def.grade - 1][choice];
            } else if (def.kind == CollectionKind::Essence) {
                const int type = combat::irand(0, def.grade == 1 ? 12 : def.grade == 2 ? 19 : 21);
                slot.random_stat_type = 100 + type;
                const int lo[][13] = {{2, 2, 2, 2, 2, 1, 1, 20, 20, 1, 1, 1, 1},
                                      {20, 20, 20, 20, 20, 4, 4, 60, 60, 3, 1, 1, 5},
                                      {40, 40, 40, 40, 40, 8, 8, 100, 100, 4, 2, 2, 10}};
                const int hi[][13] = {{20, 20, 20, 20, 20, 4, 4, 40, 40, 3, 1, 1, 10},
                                      {40, 40, 40, 40, 40, 8, 8, 80, 80, 6, 2, 2, 20},
                                      {60, 60, 60, 60, 60, 12, 12, 120, 120, 8, 3, 3, 30}};
                slot.random_stat_value =
                    type < 13    ? combat::irand(lo[def.grade - 1][type], hi[def.grade - 1][type])
                    : type >= 20 ? combat::irand(1, 10)
                                 : combat::irand(def.grade - 1, def.grade);
            }
        }

        void recompute_combat(ClientSession& c, const GameWorld& world);
        void sync_skill_buff_stats(ClientSession& c);
        void send_progression_snapshot(ClientSession& c, bool include_talents = true);
        [[nodiscard]] int learned_skill_level(const ClientSession& c, int index);

        /** Sends MSG_ADDBSTATE for one buff. */
        void send_add_bstate(ClientSession& c,
                             std::uint64_t bstate,
                             std::int32_t remain,
                             std::int32_t skill_index = 0,
                             std::int32_t item_index = 0) {
            if (!c.sock || bstate == 0) {
                return;
            }
            c.sock->enqueue(
                protocol::BuffState::frame_add(bstate, remain, skill_index, item_index));
        }

        /** Syncs the community noticeboard and the active EXP event HUD buff. */
        void sync_exp_event_to_client(ClientSession& c, const ServerEventManager& event) {
            const std::int64_t now = unix_now_sec();
            if (c.sock) {
                c.sock->enqueue(protocol::ExpEventState::frame(event.snapshot(now)));
            }
            const std::int32_t percent = event.active_bonus_percent(now);
            const std::int32_t remain = event.remaining_seconds(now);
            if (percent > 0 && remain > 0) {
                // item_index carries the dynamic percentage for this HUD-only state.
                send_add_bstate(c, protocol::kCbsExpEvent, remain, 0, percent);
            }
        }

        /** Sends MSG_SUBBSTATE for cleared bits. */
        void send_sub_bstate(ClientSession& c, std::uint64_t bstate) {
            if (!c.sock || bstate == 0) {
                return;
            }
            c.sock->enqueue(protocol::BuffState::frame_sub(bstate));
        }

        /** Expires timed pay buffs and notifies the client. */
        void tick_pay_buffs(IDataStore* store, ClientSession& c, const GameWorld& world) {
            const std::uint64_t cleared = c.pay_buffs.tick(unix_now_sec());
            if (cleared == 0) {
                return;
            }
            send_sub_bstate(c, cleared);
            persist_pay_buffs(store, c);
            if ((cleared & (protocol::kCbsFoodAttack | protocol::kCbsFoodMagic)) != 0) {
                recompute_combat(c, world);
                sync_skill_buff_stats(c);
            }
        }

        /** Syncs all active pay buffs to the client (login). */
        void sync_pay_buffs_to_client(ClientSession& c) {
            const std::int64_t now = unix_now_sec();
            for (const auto& e : c.pay_buffs.entries()) {
                const std::int32_t rem = PayBuffSet::remain_of(e, now);
                if (rem > 0) {
                    send_add_bstate(c, e.bstate, rem, 0, e.source_item_index);
                }
            }
        }

        /** Sends the current register order and remaining unlock times to the client. */
        void sync_inventory_unlocks_to_client(ClientSession& c) {
            send_sub_bstate(c, protocol::kCbsInventoryRegisterMask);
            const std::int64_t now = unix_now_sec();
            const auto& entries = c.inventory_unlocks.entries();
            for (std::size_t i = 0; i < entries.size(); ++i) {
                const std::int32_t remain = InventoryUnlockSet::remain_of(entries[i], now);
                if (remain > 0) {
                    send_add_bstate(
                        c, protocol::inventory_register_bstate(static_cast<int>(i)), remain);
                }
            }
        }

        /** Expires inventory-register unlocks and sends their updated register order. */
        void tick_inventory_unlocks(IDataStore* store, ClientSession& c) {
            if (!c.inventory_unlocks.tick(unix_now_sec())) {
                return;
            }
            sync_inventory_unlocks_to_client(c);
            (void) persist_inventory_unlocks(store, c);
        }

        /** Pushes Hit / Defense / Absorb including active skill-buff bonuses. */
        void sync_skill_buff_stats(ClientSession& c) {
            const int refining = c.skill_buffs.refining_weapon_points();
            send_cur_property(c, protocol::PropertyType::MinAttack, c.min_attack + refining);
            send_cur_property(c, protocol::PropertyType::MaxAttack, c.max_attack + refining);
            send_cur_property(c, protocol::PropertyType::MinMagic, c.min_magic + refining);
            send_cur_property(c, protocol::PropertyType::MaxMagic, c.max_magic + refining);
            send_cur_property(
                c, protocol::PropertyType::Hit, c.hit + c.skill_buffs.concentration_hit());
            send_cur_property(
                c, protocol::PropertyType::Defense, c.defense + c.skill_buffs.stone_defense());
            send_cur_property(
                c, protocol::PropertyType::Absorb, c.absorb + c.skill_buffs.stone_absorb());
        }

        /** Expires timed skill buffs and notifies the client. */
        void tick_skill_buffs(ClientSession& c, const GameWorld& world) {
            const std::uint64_t cleared = c.skill_buffs.tick(unix_now_sec());
            if (cleared != 0) {
                send_sub_bstate(c, cleared);
                recompute_combat(c, world);
                send_progression_snapshot(c);
                sync_skill_buff_stats(c);
            }
        }

        /**
         * related compatibility states IsExpired: drain MP once per second.
         * @param c Target session.
         * @param now_ms Monotonic milliseconds.
         */
        void tick_archer_mp_drain(ClientSession& c, std::uint64_t now_ms) {
            const std::int32_t drain = c.skill_buffs.archer_mana_burn_per_tick() +
                                       c.skill_buffs.archer_silence_shot_mp_drain();
            if (drain <= 0) {
                return;
            }
            if (c.next_archer_mp_drain_ms != 0 && now_ms < c.next_archer_mp_drain_ms) {
                return;
            }
            c.next_archer_mp_drain_ms = now_ms + 1000;
            c.cur_mp = combat::clamp_nonneg_i32(static_cast<std::int64_t>(c.cur_mp) - drain);
            send_cur_property(c, protocol::PropertyType::CurMp, c.cur_mp);
        }

        /** Syncs active skill buffs to the client (login). */
        void sync_skill_buffs_to_client(ClientSession& c) {
            const std::int64_t now = unix_now_sec();
            for (const auto& e : c.skill_buffs.entries()) {
                if (e.bstate == 0) {
                    continue;
                }
                const std::int32_t rem = SkillBuffSet::remain_of(e, now);
                if (rem > 0 || e.expire_unix == 0) {
                    send_add_bstate(c, e.bstate, rem, e.skill_index);
                }
            }
        }

        /**
         * Perfect Defense proc (10% absorb).
         * @return True when the hit was fully absorbed.
         */
        [[nodiscard]] bool try_perfect_defense(IDataStore* store, ClientSession& c) {
            if (!c.pay_buffs.has(protocol::kCbsPayPerfectDef)) {
                return false;
            }
            if (combat::irand(1, 100) > 10) {
                return false;
            }
            std::int32_t remain = 0;
            bool removed = false;
            if (!c.pay_buffs.consume_charge(
                    static_cast<int>(protocol::BuffType::PayPerfectDef), remain, removed)) {
                return false;
            }
            if (removed) {
                send_sub_bstate(c, protocol::kCbsPayPerfectDef);
            } else {
                send_add_bstate(c, protocol::kCbsPayPerfectDef, remain);
            }
            persist_pay_buffs(store, c);
            return true;
        }

        /**
         * HP Absorb proc after dealing damage to a monster (10%).
         * @param dealt Damage dealt to the monster.
         */
        void try_drain_hp(IDataStore* store, ClientSession& c, std::int32_t dealt) {
            if (dealt <= 0 || !c.pay_buffs.has(protocol::kCbsPayDrainHp)) {
                return;
            }
            if (combat::irand(1, 100) > 10) {
                return;
            }
            std::int32_t remain = 0;
            bool removed = false;
            if (!c.pay_buffs.consume_charge(
                    static_cast<int>(protocol::BuffType::PayDrainHp), remain, removed)) {
                return;
            }
            using player_regen::add_clamped;
            if (add_clamped(c.cur_hp, c.max_hp, dealt)) {
                send_cur_property(c, protocol::PropertyType::CurHp, c.cur_hp);
            }
            if (removed) {
                send_sub_bstate(c, protocol::kCbsPayDrainHp);
            } else {
                send_add_bstate(c, protocol::kCbsPayDrainHp, remain);
            }
            persist_pay_buffs(store, c);
        }

        void persist_skill_changes(IDataStore* store,
                                   std::int32_t character_id,
                                   const std::vector<SkillRankChange>& changes) {
            if (!store || character_id <= 0) {
                return;
            }
            for (const SkillRankChange& change : changes) {
                SkillRecord rec;
                rec.character_id = character_id;
                rec.skill_index = change.index;
                rec.level = change.level;
                (void) store->upsert_skill(rec);
            }
        }

        void persist_shortcuts(IDataStore* store,
                               std::int32_t character_id,
                               const protocol::ShortcutBar& bar) {
            if (!store || character_id <= 0) {
                return;
            }
            ShortcutRecord rec;
            rec.character_id = character_id;
            rec.active_index = bar.active_index;
            rec.slots = bar.slots;
            (void) store->upsert_shortcuts(rec);
        }

        [[nodiscard]] const ItemCombatDef* item_def_of(const GameWorld& world, int index) {
            const auto& items = world.item_defs();
            auto it = items.find(index);
            if (it == items.end()) {
                return nullptr;
            }
            return &it->second;
        }

        [[nodiscard]] int persist_slot_for(const GameWorld& world,
                                           const ClientSession::BagSlot& slot) {
            if (!slot.equipped || slot.index <= 0) {
                return 0;
            }
            const ItemCombatDef* def = item_def_of(world, slot.index);
            if (!def) {
                return 0;
            }
            return persist_slot_of(wear_kind_of(*def));
        }

        void persist_item_row(IDataStore* store,
                              const GameWorld& world,
                              const ClientSession& c,
                              const ClientSession::BagSlot& slot) {
            if (!store || c.character_id <= 0 || slot.iid == 0) {
                return;
            }
            ItemRecord rec;
            fill_item_record_from_slot(rec, c, slot, persist_slot_for(world, slot));
            (void) store->update_item(rec);
        }

        void persist_new_item(IDataStore* store,
                              const ClientSession& c,
                              const ClientSession::BagSlot& slot) {
            if (!store || c.character_id <= 0 || slot.iid == 0) {
                return;
            }
            ItemRecord rec;
            fill_item_record_from_slot(rec, c, slot, 0);
            (void) store->insert_item(rec);
        }

        /** Moves one equipment instance only after its new location is persisted. */
        [[nodiscard]] bool move_equipment_item(IDataStore* store,
                                               const GameWorld& world,
                                               ClientSession& c,
                                               ClientSession::BagSlot& source,
                                               ClientSession::BagSlot& destination,
                                               bool equipped) {
            auto moved = source;
            moved.equipped = equipped;
            const auto kind = collection_def(moved.index).kind;
            if (equipped && (kind == CollectionKind::Mirror || kind == CollectionKind::Taegeuk)) {
                moved.account_bound = true;
            }
            if (equipped && kind == CollectionKind::Mirror && moved.pet_expire_at == 0) {
                moved.pet_expire_at = unix_now_sec() + 7 * 86400;
            }
            if (store && c.character_id > 0) {
                ItemRecord record;
                fill_item_record_from_slot(record, c, moved, persist_slot_for(world, moved));
                if (!store->update_item(record)) {
                    return false;
                }
            }
            destination = moved;
            source = {};
            return true;
        }

        /** Writes worn animal level/EXP onto a bag slot (compatibility behavior / runtime state).
         * @param slot Inventory slot that owns the egg.
         * @param tf Worn transform working copy.
         */
        void write_transform_progress_to_slot(ClientSession::BagSlot& slot,
                                              const player_regen::TransformExpState& tf) {
            slot.transform_level = tf.level < 1 ? 1 : tf.level;
            slot.transform_exp = tf.exp < 0 ? 0 : tf.exp;
        }

        /** Copies worn animal progress onto the equipped egg in the bag.
         * @param c Player whose worn transform is flushed.
         */
        void sync_transform_progress_to_equipped_item(ClientSession& c) {
            if (c.transform.index <= 0) {
                return;
            }
            for (auto& slot : c.bag) {
                if (slot.equipped && slot.index == c.transform.index) {
                    write_transform_progress_to_slot(slot, c.transform);
                    return;
                }
            }
        }

        /** Loads animal level/EXP from a bag egg into the worn transform state.
         * @param c Player that will wear the egg.
         * @param slot Inventory slot that owns the egg.
         * @param index Item index of the egg.
         */
        void apply_transform_progress_from_slot(ClientSession& c,
                                                const ClientSession::BagSlot& slot,
                                                int index) {
            c.transform.index = index;
            c.transform.level = slot.transform_level < 1 ? 1 : slot.transform_level;
            c.transform.exp = slot.transform_exp < 0 ? 0 : slot.transform_exp;
        }

        void persist_quest_flag(IDataStore* store,
                                const ClientSession& c,
                                const protocol::QuestFlagEntry& entry) {
            if (!store || c.character_id <= 0) {
                return;
            }
            QuestFlagRecord rec;
            rec.character_id = c.character_id;
            rec.quest = entry.quest;
            rec.flag = entry.flag;
            rec.clear = entry.clear;
            (void) store->upsert_quest_flag(rec);
        }

        /** Event-job quest range (NewPlayer inserts 9001/1/0). */
        constexpr std::uint16_t kEventQuestBegin = 9001;
        constexpr std::uint16_t kEventQuestEnd = 9011;

        [[nodiscard]] bool has_event_quest(const PlayerQuestMap& quests) {
            for (const auto& [id, _] : quests) {
                if (id >= kEventQuestBegin && id <= kEventQuestEnd) {
                    return true;
                }
            }
            return false;
        }

        /** Grants Chun-Sooin starter flag 9001/1 when no event quest exists yet. */
        void ensure_starter_event_quest(IDataStore* store, ClientSession& c) {
            if (has_event_quest(c.quests)) {
                return;
            }
            protocol::QuestFlagEntry entry;
            entry.quest = kEventQuestBegin;
            entry.flag = 1;
            entry.clear = 0;
            c.quests[kEventQuestBegin] = entry;
            persist_quest_flag(store, c, entry);
        }

        /** Sends MSG_SPECIALTYUP so the client can resolve the government title. */
        void send_specialty_up(ClientSession& c) {
            if (!c.sock) {
                return;
            }
            c.sock->enqueue(protocol::ItemMonster::frame_message_v(
                static_cast<std::uint8_t>(protocol::InfoMsg::SpecialtyUp),
                static_cast<std::uint8_t>(std::clamp(c.specialty, 0, 255))));
        }

        void persist_session_logout(IDataStore* store, ClientSession& c) {
            if (c.phase != SessionPhase::Playing) {
                return;
            }
            (void) persist_character(store, c);
            (void) persist_pay_buffs(store, c);
        }

        /** Returns a writable General cell for an equipment removal, or nullptr. */
        [[nodiscard]] ClientSession::BagSlot* equipment_return_cell(ClientSession& c) {
            for (int i = 0; i < unlocked_bag_slot_count(c); ++i) {
                if (c.bag[i].iid == 0) {
                    return &c.bag[i];
                }
            }
            return nullptr;
        }

        /** Saves an ordinary equip/swap before changing either in-memory location. */
        [[nodiscard]] bool equip_ordinary_item(IDataStore* store,
                                               const GameWorld& world,
                                               ClientSession& c,
                                               ClientSession::BagSlot*& source,
                                               WearKind kind,
                                               ClientSession::BagSlot& previous) {
            if (kind <= WearKind::None ||
                (kind >= WearKind::Collection && kind != WearKind::AssassinMask) ||
                source->equipped || source->count != 1) {
                return false;
            }
            auto& worn = c.bag[ClientSession::kBagSlots + static_cast<int>(kind) - 1];
            auto incoming = *source;
            incoming.equipped = true;
            if (kind == WearKind::Pet) {
                incoming.account_bound = true;
                const auto pet = world.pet_defs().find(incoming.index);
                if (pet != world.pet_defs().end() && pet->second.duration_seconds > 0 &&
                    incoming.pet_expire_at == 0) {
                    incoming.pet_expire_at = unix_now_sec() + pet->second.duration_seconds;
                }
            }
            if (kind == WearKind::Ride) {
                incoming.account_bound = true;
                const auto ride = world.riding_defs().find(incoming.index);
                if (ride != world.riding_defs().end() && ride->second.duration_seconds > 0 &&
                    incoming.ride_expire_at == 0) {
                    incoming.ride_expire_at = unix_now_sec() + ride->second.duration_seconds;
                }
            }
            auto& previous_wear =
                kind == WearKind::AssassinMask
                    ? c.bag[ClientSession::kBagSlots + static_cast<int>(WearKind::Face) - 1]
                    : worn;
            previous = previous_wear;
            auto* returned = source;
            if (previous.iid != 0 && source >= c.bag.data() + unlocked_bag_slot_count(c)) {
                returned = equipment_return_cell(c);
                if (!returned) {
                    return false;
                }
            }
            if (previous.iid != 0) {
                if (kind == WearKind::Transform) {
                    write_transform_progress_to_slot(previous, c.transform);
                }
                previous.equipped = false;
            }
            std::vector<ItemRecord> records(1);
            fill_item_record_from_slot(records[0], c, incoming, persist_slot_for(world, incoming));
            if (previous.iid != 0) {
                records.emplace_back();
                fill_item_record_from_slot(records.back(), c, previous, 0);
            }
            if (store && c.character_id > 0 && !store->update_equipment_items(records)) {
                return false;
            }
            *source = {};
            previous_wear = {};
            *returned = previous;
            worn = incoming;
            source = &worn;
            return true;
        }

        /** Atomically returns conflicting cosmetics before occupying the new skin slot. */
        [[nodiscard]] bool equip_skin_item(IDataStore* store,
                                           const GameWorld& world,
                                           ClientSession& c,
                                           ClientSession::BagSlot*& source,
                                           const ItemCombatDef& incoming_def,
                                           std::vector<ClientSession::BagSlot>& removed,
                                           std::string& error) {
            if (source->equipped || source->count != 1 ||
                incoming_def.skin_slot == protocol::SkinSlot::None) {
                return false;
            }
            const auto source_cell = static_cast<std::size_t>(source - c.bag.data());
            if (source_cell >= ClientSession::kBagSlots) {
                return false;
            }
            if (incoming_def.skin_slot == protocol::SkinSlot::Weapon) {
                const auto* weapon = item_def_of(world, c.weapon_index);
                if (!weapon || !weapon->is_weapon ||
                    incoming_def.skin_weapon_type == protocol::WeaponSkinType::None ||
                    incoming_def.skin_weapon_type !=
                        protocol::weapon_skin_type_for_name(weapon->class_small)) {
                    error = "This skin requires an equipped weapon of the matching type.";
                    return false;
                }
            }
            auto updated = c.bag;
            auto incoming = updated[source_cell];
            updated[source_cell] = {};
            incoming.equipped = true;
            std::vector<ItemRecord> records(1);
            fill_item_record_from_slot(records.front(), c, incoming, 6);
            for (std::size_t i = ClientSession::kBagSlots; i < updated.size(); ++i) {
                const auto* existing = item_def_of(world, updated[i].index);
                if (!updated[i].equipped || !existing ||
                    !protocol::skin_slots_conflict(incoming_def.skin_slot,
                                                   incoming_def.full_body_skin,
                                                   existing->skin_slot,
                                                   existing->full_body_skin)) {
                    continue;
                }
                auto returned = updated[i];
                returned.equipped = false;
                auto destination = updated.begin();
                for (; destination != updated.begin() + unlocked_bag_slot_count(c); ++destination) {
                    if (destination->iid == 0) {
                        break;
                    }
                }
                if (destination == updated.begin() + unlocked_bag_slot_count(c)) {
                    error = "Not enough inventory space to put away the equipped skins.";
                    return false;
                }
                *destination = returned;
                updated[i] = {};
                removed.push_back(returned);
                records.emplace_back();
                fill_item_record_from_slot(records.back(), c, returned, 0);
            }
            const auto cell = ClientSession::kBagSlots + static_cast<int>(WearKind::SkinWeapon) +
                              static_cast<int>(incoming_def.skin_slot) - 1;
            updated[cell] = incoming;
            if (store && c.character_id > 0 && !store->update_equipment_items(records)) {
                return false;
            }
            c.bag = updated;
            source = &c.bag[cell];
            return true;
        }

        void refresh_visual_wear(ClientSession& c, const GameWorld& world) {
            c.skin_wear.fill(0);
            c.visual_shield = 0;
            std::fill(std::begin(c.wear), std::end(c.wear), 0);
            int weapon_index = 0;
            int weapon_prefix = 0;
            std::uint32_t weapon_iid = 0;
            int armor_index = 0;
            int armor_prefix = 0;
            std::uint32_t armor_iid = 0;
            int transform_index = 0;
            for (const auto& slot : c.bag) {
                if (!slot.equipped || slot.count <= 0 || slot.index <= 0) {
                    continue;
                }
                const ItemCombatDef* def = item_def_of(world, slot.index);
                if (!def) {
                    continue;
                }
                if (def->skin_slot != protocol::SkinSlot::None) {
                    c.skin_wear[static_cast<std::size_t>(def->skin_slot)] =
                        static_cast<std::uint16_t>(slot.index);
                    continue;
                }
                const auto kind = wear_kind_of(*def);
                if (kind == WearKind::Boots) {
                    c.wear[1] = static_cast<std::uint16_t>(slot.index);
                }
                if (kind == WearKind::Gauntlet) {
                    c.wear[2] = static_cast<std::uint16_t>(slot.index);
                }
                if (kind == WearKind::Pants) {
                    c.wear[4] = static_cast<std::uint16_t>(slot.index);
                }
                if (kind == WearKind::Face) {
                    c.wear[5] = static_cast<std::uint16_t>(slot.index);
                }
                if (kind == WearKind::Helmet) {
                    c.wear[6] = static_cast<std::uint16_t>(slot.index);
                }
                if (kind == WearKind::Shield) {
                    c.visual_shield = static_cast<std::uint16_t>(slot.index);
                }
                switch (kind) {
                case WearKind::Weapon:
                    weapon_index = slot.index;
                    weapon_prefix = slot.prefix;
                    weapon_iid = slot.iid;
                    break;
                case WearKind::Upper:
                    armor_index = slot.index;
                    armor_prefix = slot.prefix;
                    armor_iid = slot.iid;
                    break;
                case WearKind::Transform:
                    transform_index = slot.index;
                    break;
                default:
                    break;
                }
            }
            c.weapon_index = weapon_index;
            const auto* weapon_skin = item_def_of(world, c.skin_wear[0]);
            const auto* actual_weapon = item_def_of(world, weapon_index);
            if (weapon_skin &&
                (!actual_weapon || !actual_weapon->is_weapon ||
                 weapon_skin->skin_weapon_type == protocol::WeaponSkinType::None ||
                 weapon_skin->skin_weapon_type !=
                     protocol::weapon_skin_type_for_name(actual_weapon->class_small))) {
                c.skin_wear[0] = 0;
            }
            c.weapon_prefix = weapon_prefix;
            c.weapon_iid = weapon_iid;
            c.armor_index = armor_index;
            c.armor_prefix = armor_prefix;
            c.armor_iid = armor_iid;
            if (transform_index == 0) {
                c.transform = {};
            } else if (c.transform.index != transform_index) {
                c.transform.index = transform_index;
            }
        }

        void unequip_same_kind(IDataStore* store,
                               const GameWorld& world,
                               ClientSession& c,
                               WearKind kind,
                               std::uint32_t except_iid) {
            if (kind == WearKind::None) {
                return;
            }
            if (kind == WearKind::Transform) {
                sync_transform_progress_to_equipped_item(c);
            }
            for (auto& slot : c.bag) {
                if (!slot.equipped || slot.iid == except_iid || slot.index <= 0) {
                    continue;
                }
                const ItemCombatDef* def = item_def_of(world, slot.index);
                if (!def || wear_kind_of(*def) != kind) {
                    continue;
                }
                auto* destination = equipment_return_cell(c);
                if (!destination) {
                    // Login may retain expired General overflow, but must not discard equipment.
                    for (int i = 0; i < ClientSession::kGeneralSlots; ++i) {
                        if (c.bag[i].iid == 0) {
                            destination = &c.bag[i];
                            break;
                        }
                    }
                }
                if (destination) {
                    (void) move_equipment_item(store, world, c, slot, *destination, false);
                }
            }
        }

        /** Immutable borrowed inputs for one equipment/profile calculation. */
        struct CombatInputs {
            const ClientSession& session;
            const GameWorld& world;
            /** Requested calculation profile, independent of the live profile/deadline. */
            bool collection_pve;
            /** External guild bonuses captured once before calculation. */
            std::array<int, 3> guild_bonus;
        };

        /** Owned derived state; calculating it never mutates its source session. */
        struct CombatResult {
            /** Effective class bases, committed only by authoritative recomputation. */
            combat::BaseStats base_stats;
            combat::BaseStats prefix_bonus;
            CollectionBonuses collection_bonus;
            std::int32_t min_attack = 0;
            std::int32_t max_attack = 0;
            std::int32_t min_magic = 0;
            std::int32_t max_magic = 0;
            std::int32_t hit = 0;
            std::int32_t dodge = 0;
            std::int32_t defense = 0;
            std::int32_t defense_range = 0;
            std::int32_t absorb = 0;
            std::int32_t fatal_rate = 0;
            std::int32_t fatal_pt = 0;
            std::int32_t perfect_evasion_base = 0;
            std::int32_t perfect_evasion_advanced = 0;
            std::int32_t block_percent = 0;
            bool wearing_shield = false;
            bool wearing_two_hand = false;
            int upgrade_level = 0;
            int char_attack = 0;
            int char_magic = 0;
            int weapon_min_attack = 0;
            int weapon_max_attack = 0;
            int weapon_min_magic = 0;
            int weapon_max_magic = 0;
            std::int32_t res_fire = 0;
            std::int32_t res_ice = 0;
            std::int32_t res_lightning = 0;
            std::int32_t res_curse = 0;
            std::int32_t res_palsy = 0;
            int attack_range = 16;
            int attack_speed_ms = 700;
            std::int32_t max_hp = 0;
            std::int32_t max_mp = 0;
            std::int32_t cur_hp = 0;
            std::int32_t cur_mp = 0;
            /** Visual values for wear slots 0 and 3; other slots remain unchanged. */
            std::uint16_t weapon_wear = 0;
            std::uint16_t armor_wear = 0;
            int transform_mspeed_percent = 0;
            std::uint32_t gstate = 0;
        };

        /** Captures external guild state once at the calculation boundary. */
        [[nodiscard]] CombatInputs
        capture_combat_inputs(const ClientSession& c, const GameWorld& world, bool collection_pve) {
            return {c,
                    world,
                    collection_pve,
                    g_guilds ? g_guilds->bonuses(c.character_id) : std::array<int, 3>{}};
        }

        /** Calculates ordered equipment, class, resource, and profile contributions. */
        [[nodiscard]] CombatResult calculate_combat(const CombatInputs& input) {
            const auto& c = input.session;
            const auto& world = input.world;
            CombatResult result;
            result.cur_hp = c.cur_hp;
            result.cur_mp = c.cur_mp;
            result.gstate = c.gstate;
            // Initialize effective primaries before applying ordered contributions.
            result.collection_bonus =
                collection_bonuses(collection_items(c), !input.collection_pve);
            const auto& collection = result.collection_bonus;
            result.base_stats = c.stats_initialized
                                    ? combat::BaseStats{c.str, c.hth, c.intl, c.wis, c.dex}
                                    : combat::class_base_plus_bonus(c.clazz);
            combat::BaseStats stats;
            const auto& guild_bonus = input.guild_bonus;
            stats.str = result.base_stats.str + guild_bonus[0];
            stats.hth = result.base_stats.hth + guild_bonus[0];
            stats.intl = result.base_stats.intl + guild_bonus[0];
            stats.wis = result.base_stats.wis + guild_bonus[0];
            stats.dex = result.base_stats.dex + guild_bonus[0];
            stats.str += static_cast<int>(collection.ability[0]);
            stats.wis += static_cast<int>(collection.ability[1]);
            stats.intl += static_cast<int>(collection.ability[2]);
            stats.hth += static_cast<int>(collection.ability[3]);
            stats.dex += static_cast<int>(collection.ability[4]);
            const auto apply_primary_curse = [&](SkillBuffId id, std::int32_t& stat) {
                std::int32_t percent = 0;
                std::int32_t unused = 0;
                if (c.skill_buffs.values(id, percent, unused)) {
                    stat =
                        combat::clamp_nonneg_i32(static_cast<std::int64_t>(stat) +
                                                 static_cast<std::int64_t>(stat) * percent / 100);
                }
            };
            apply_primary_curse(SkillBuffId::ArcherCurseStrength, stats.str);
            apply_primary_curse(SkillBuffId::ArcherCurseHealth, stats.hth);
            apply_primary_curse(SkillBuffId::ArcherCurseAgility, stats.dex);
            apply_primary_curse(SkillBuffId::ArcherCurseIntelligence, stats.intl);
            apply_primary_curse(SkillBuffId::ArcherCurseWisdom, stats.wis);

            struct WornGear {
                const ItemCombatDef* item = nullptr;
                const PrefixCombatDef* prefix = nullptr;
                CharmState charm{};
                int bof = 0;
                int qigong_effect = 0;
                int dragon_effect = 0;
                int random_stat_type = 0;
                int random_stat_value = 0;
            };
            std::vector<WornGear> worn;
            worn.reserve(12);
            // Collect worn gear and preserve legacy catalog fallbacks.
            const auto& prefixes = world.prefix_defs();
            auto prefix_of = [&](int prefix) -> const PrefixCombatDef* {
                if (prefix <= 0) {
                    return nullptr;
                }
                auto it = prefixes.find(prefix);
                if (it == prefixes.end()) {
                    return nullptr;
                }
                return &it->second;
            };
            for (const auto& slot : c.bag) {
                if (!slot.equipped || slot.count <= 0 || slot.index <= 0) {
                    continue;
                }
                const ItemCombatDef* item = item_def_of(world, slot.index);
                if (!item) {
                    continue;
                }
                // Collection bonuses are evaluated separately for PvE. Never add them
                // to the baseline used by player-versus-player combat.
                if (collection_def(slot.index).kind != CollectionKind::None ||
                    item->class_big == "skin") {
                    continue;
                }
                CharmState charm;
                charm.x_attack = slot.x_attack;
                charm.x_magic = slot.x_magic;
                charm.x_hit = slot.x_hit;
                charm.x_defense = slot.x_defense;
                charm.x_dodge = slot.x_dodge;
                charm.upgrade_level = slot.upgrade_level;
                charm.upgrade_rate = slot.upgrade_rate;
                charm.cur_end = slot.cur_end;
                charm.max_end = slot.max_end;
                worn.push_back(WornGear{item,
                                        prefix_of(slot.prefix),
                                        charm,
                                        slot.bof,
                                        slot.qigong_effect,
                                        slot.dragon_effect,
                                        slot.random_stat_type,
                                        slot.random_stat_value});
                if (wear_kind_of(*item) == WearKind::Shield) {
                    result.wearing_shield = true;
                }
                if (item->is_weapon && item->class_small == "sword2h") {
                    result.wearing_two_hand = true;
                }
            }
            if (worn.empty()) {
                if (c.weapon_index > 0) {
                    if (const ItemCombatDef* item = item_def_of(world, c.weapon_index)) {
                        worn.push_back(WornGear{item, prefix_of(c.weapon_prefix)});
                    }
                }
                if (c.armor_index > 0) {
                    if (const ItemCombatDef* item = item_def_of(world, c.armor_index)) {
                        worn.push_back(WornGear{item, prefix_of(c.armor_prefix)});
                    }
                }
            }

            // Mix effect is attached to the equipped weapon instance (BagSlot).
            // Decoding scheme:
            //   mix_type low 4 bits: stone type (1..11), mix_type high nibble: mix level (1..2).
            int weapon_mix_type = 0;
            if (c.weapon_iid != 0) {
                for (const auto& slot : c.bag) {
                    if (slot.equipped && slot.iid == c.weapon_iid) {
                        weapon_mix_type = slot.mix_type;
                        break;
                    }
                }
            } else if (c.weapon_index > 0) {
                for (const auto& slot : c.bag) {
                    if (slot.equipped && slot.count > 0 && slot.index == c.weapon_index) {
                        weapon_mix_type = slot.mix_type;
                        break;
                    }
                }
            }
            const int mix_stone_type = weapon_mix_type & 0x0F;
            const int mix_level = (weapon_mix_type >> 4) & 0x03;  // 1..2

            // Only the "stat" part of mix is applied here.
            int mix_str_add = 0;
            int mix_hth_add = 0;
            int mix_int_add = 0;
            int mix_wis_add = 0;
            int mix_dex_add = 0;
            int mix_hp_flat_add = 0;
            int mix_mp_flat_add = 0;
            int mix_hp_pct_add = 0;
            int mix_mp_pct_add = 0;
            int fanta_attack_add = 0;
            int random_min_attack_percent = 0;
            int random_max_attack_percent = 0;
            int random_min_magic_percent = 0;
            int random_max_magic_percent = 0;
            int random_defense_points = 0;
            int random_defense_percent = 0;

            // Decode weapon mix stat contributions.
            if (mix_stone_type != 0 && mix_level != 0) {
                switch (mix_stone_type) {
                case 1:  // Dark (ITEM_MIX_DARK)
                    if (mix_level == 1) {
                        mix_hp_flat_add = 20;
                        mix_str_add = 2;
                        mix_int_add = 2;
                        mix_dex_add = 2;
                    } else if (mix_level == 2) {
                        mix_hp_flat_add = 50;
                        mix_str_add = 3;
                        mix_int_add = 3;
                        mix_dex_add = 3;
                    }
                    break;
                case 2:  // Saint (ITEM_MIX_SAINT)
                    if (mix_level == 1) {
                        mix_mp_flat_add = 20;
                        mix_wis_add = 2;
                        mix_hth_add = 2;
                    } else if (mix_level == 2) {
                        mix_mp_flat_add = 50;
                        mix_wis_add = 5;
                        mix_hth_add = 5;
                    }
                    break;
                case 8:  // Power (ITEM_MIX_POWER)
                    if (mix_level == 1) {
                        mix_hp_pct_add = 10;
                        mix_mp_pct_add = -5;
                    } else if (mix_level == 2) {
                        mix_hp_pct_add = 20;
                        mix_mp_pct_add = -10;
                    }
                    break;
                case 9:  // Tech (ITEM_MIX_TECH)
                    if (mix_level == 1) {
                        mix_hp_pct_add = -5;
                        mix_mp_pct_add = 10;
                    } else if (mix_level == 2) {
                        mix_hp_pct_add = -10;
                        mix_mp_pct_add = 20;
                    }
                    break;
                case 10:  // Fanta (ITEM_MIX_FANTA)
                    fanta_attack_add = 50;
                    break;
                case 11:  // Blood (ITEM_MIX_BLOOD)
                    mix_hp_flat_add = 50;
                    mix_mp_flat_add = 50;
                    mix_str_add = 6;
                    mix_int_add = 6;
                    mix_dex_add = 6;
                    mix_hth_add = 10;
                    mix_wis_add = 10;
                    break;
                default:
                    break;  // Flame/Ice/Light/Poison/Paral mix handled later.
                }
            }

            const auto apply_primary_bonus = [&](int primary_kind, int primary_points) {
                switch (primary_kind) {
                case 0:
                    stats.str += primary_points;
                    break;
                case 1:
                    stats.hth += primary_points;
                    break;
                case 2:
                    stats.dex += primary_points;
                    break;
                case 3:
                    stats.wis += primary_points;
                    break;
                case 4:
                    stats.intl += primary_points;
                    break;
                default:
                    break;
                }
            };
            const auto collect_random_item_stat = [&](const WornGear& gear) {
                const int value = std::clamp(gear.random_stat_value, 0, 5);
                if (value == 0) {
                    return;
                }
                switch (static_cast<protocol::RandomItemStatType>(gear.random_stat_type)) {
                case protocol::RandomItemStatType::WeaponMinPhysicalDamagePercent:
                    random_min_attack_percent += value;
                    break;
                case protocol::RandomItemStatType::WeaponMinMagicalDamagePercent:
                    random_min_magic_percent += value;
                    break;
                case protocol::RandomItemStatType::WeaponMaxPhysicalDamagePercent:
                    random_max_attack_percent += value;
                    break;
                case protocol::RandomItemStatType::WeaponMaxMagicalDamagePercent:
                    random_max_magic_percent += value;
                    break;
                case protocol::RandomItemStatType::WeaponPhysicalDamagePercent:
                    random_min_attack_percent += value;
                    random_max_attack_percent += value;
                    break;
                case protocol::RandomItemStatType::WeaponMagicalDamagePercent:
                    random_min_magic_percent += value;
                    random_max_magic_percent += value;
                    break;
                case protocol::RandomItemStatType::ArmorStrength:
                    stats.str += value;
                    break;
                case protocol::RandomItemStatType::ArmorHealth:
                    stats.hth += value;
                    break;
                case protocol::RandomItemStatType::ArmorIntelligence:
                    stats.intl += value;
                    break;
                case protocol::RandomItemStatType::ArmorWisdom:
                    stats.wis += value;
                    break;
                case protocol::RandomItemStatType::ArmorDexterity:
                    stats.dex += value;
                    break;
                case protocol::RandomItemStatType::ArmorDefense:
                    random_defense_points += value;
                    break;
                case protocol::RandomItemStatType::ArmorDefensePercent:
                    random_defense_percent += value;
                    break;
                case protocol::RandomItemStatType::ArmorDefensePercentStrength:
                    random_defense_percent += value;
                    stats.str += value;
                    break;
                case protocol::RandomItemStatType::ArmorDefensePercentHealth:
                    random_defense_percent += value;
                    stats.hth += value;
                    break;
                case protocol::RandomItemStatType::ArmorDefensePercentIntelligence:
                    random_defense_percent += value;
                    stats.intl += value;
                    break;
                case protocol::RandomItemStatType::ArmorDefensePercentWisdom:
                    random_defense_percent += value;
                    stats.wis += value;
                    break;
                case protocol::RandomItemStatType::ArmorDefensePercentDexterity:
                    random_defense_percent += value;
                    stats.dex += value;
                    break;
                case protocol::RandomItemStatType::ArmorDefensePercentDefense:
                    random_defense_percent += value;
                    random_defense_points += value;
                    break;
                case protocol::RandomItemStatType::None:
                default:
                    break;
                }
            };
            // Apply primary contributions and revise base combat values.
            for (const auto& gear : worn) {
                if (gear.item) {
                    gear.item->apply_primaries(
                        stats.str, stats.hth, stats.intl, stats.wis, stats.dex);
                }
                if (gear.prefix) {
                    gear.prefix->apply_primaries(
                        stats.str, stats.hth, stats.intl, stats.wis, stats.dex);
                }
                const QigongBonus qigong = QigongBonus::from_effect(
                    gear.qigong_effect,
                    gear.item && gear.item->is_weapon,
                    gear.item ? gear.item->class_small : std::string_view{});
                apply_primary_bonus(qigong.primary_kind(), qigong.primary_points());
                const DragonFusingBonus dragon = DragonFusingBonus::from_effect(
                    gear.dragon_effect,
                    gear.item && gear.item->is_weapon,
                    gear.item ? gear.item->class_small : std::string_view{});
                apply_primary_bonus(dragon.primary_kind(), dragon.primary_points());
                collect_random_item_stat(gear);
            }

            std::vector<BofWornPiece> bof_pieces;
            for (const auto& gear : worn) {
                if (!gear.item || gear.bof == 0) {
                    continue;
                }
                if (!world.bof().is_bof_armor_part(gear.item->class_small)) {
                    continue;
                }
                BofWornPiece piece;
                piece.set_grade(gear.item->grade);
                bof_pieces.push_back(piece);
            }
            const BofCombatBonus bof_bonus = world.bof().compute_bonus(c.clazz, bof_pieces);
            stats.str += bof_bonus.str();
            stats.hth += bof_bonus.hth();
            stats.intl += bof_bonus.intl();
            stats.dex += bof_bonus.dex();

            // Apply mix-primary stat additions (PutOn() UpdatePrtyPt()).
            stats.str += mix_str_add;
            stats.hth += mix_hth_add;
            stats.intl += mix_int_add;
            stats.wis += mix_wis_add;
            stats.dex += mix_dex_add;
            stats.str += c.skill_buffs.blessing_strength_points();
            stats.hth += c.skill_buffs.blessing_health_points();
            stats.dex += c.skill_buffs.blessing_agility_points();
            stats.intl += c.skill_buffs.blessing_intelligence_points();
            if (c.transform.index > 0) {
                const ItemCombatDef* egg = item_def_of(world, c.transform.index);
                if (egg && egg->is_transform) {
                    const auto bonus =
                        protocol::worn_transform_bonus(egg->transform_race, c.transform.level);
                    stats.str += bonus.str;
                    stats.hth += bonus.hth;
                    stats.intl += bonus.intl;
                    stats.wis += bonus.wis;
                    stats.dex += bonus.dex;
                }
            }
            result.prefix_bonus.str = stats.str - result.base_stats.str;
            result.prefix_bonus.hth = stats.hth - result.base_stats.hth;
            result.prefix_bonus.intl = stats.intl - result.base_stats.intl;
            result.prefix_bonus.wis = stats.wis - result.base_stats.wis;
            result.prefix_bonus.dex = stats.dex - result.base_stats.dex;
            combat::apply_stat_revise(c.level,
                                      stats,
                                      result.min_attack,
                                      result.max_attack,
                                      result.hit,
                                      result.dodge,
                                      result.min_magic,
                                      result.max_magic,
                                      result.res_fire,
                                      result.res_ice,
                                      result.res_lightning,
                                      result.res_curse,
                                      result.res_palsy);
            result.char_attack = result.max_attack;
            result.char_magic = result.max_magic;

            // Apply derived gear and prefix contributions in order.
            for (const auto& gear : worn) {
                if (!gear.item) {
                    continue;
                }
                gear.item->apply_gear(result.hit,
                                      result.dodge,
                                      result.min_attack,
                                      result.max_attack,
                                      result.min_magic,
                                      result.max_magic,
                                      result.defense,
                                      result.defense_range,
                                      result.absorb,
                                      result.fatal_rate,
                                      result.fatal_pt,
                                      result.res_fire,
                                      result.res_ice,
                                      result.res_lightning,
                                      result.res_curse,
                                      result.res_palsy);
                apply_equipped_charm(gear.charm,
                                     gear.item->is_weapon,
                                     gear.item->is_defense,
                                     result.min_attack,
                                     result.max_attack,
                                     result.min_magic,
                                     result.max_magic,
                                     result.hit,
                                     result.dodge,
                                     result.defense,
                                     result.defense_range);
                const QigongBonus qigong = QigongBonus::from_effect(
                    gear.qigong_effect, gear.item->is_weapon, gear.item->class_small);
                result.hit += qigong.hit();
                result.dodge += qigong.dodge();
                result.defense += qigong.defense();
                result.defense_range += qigong.defense();
                const DragonFusingBonus dragon = DragonFusingBonus::from_effect(
                    gear.dragon_effect, gear.item->is_weapon, gear.item->class_small);
                result.hit += dragon.hit();
                result.dodge += dragon.dodge();
                result.defense += dragon.defense();
                result.defense_range += dragon.defense();
                if (gear.item->is_weapon) {
                    result.weapon_min_attack +=
                        gear.item->min_attack + charm_bonus_attack(gear.charm.x_attack);
                    result.weapon_max_attack +=
                        gear.item->max_attack + charm_bonus_attack(gear.charm.x_attack);
                    result.weapon_min_magic +=
                        gear.item->min_magic + charm_bonus_attack(gear.charm.x_magic);
                    result.weapon_max_magic +=
                        gear.item->max_magic + charm_bonus_attack(gear.charm.x_magic);
                    result.upgrade_level = std::max(result.upgrade_level, gear.charm.upgrade_level);
                    result.min_attack += result.min_attack * qigong.attack_percent() / 100;
                    result.max_attack += result.max_attack * qigong.attack_percent() / 100;
                    result.min_magic += result.min_magic * qigong.magic_percent() / 100;
                    result.max_magic += result.max_magic * qigong.magic_percent() / 100;
                    result.weapon_min_attack +=
                        result.weapon_min_attack * qigong.attack_percent() / 100;
                    result.weapon_max_attack +=
                        result.weapon_max_attack * qigong.attack_percent() / 100;
                    result.weapon_min_magic +=
                        result.weapon_min_magic * qigong.magic_percent() / 100;
                    result.weapon_max_magic +=
                        result.weapon_max_magic * qigong.magic_percent() / 100;
                    result.min_attack += result.min_attack * dragon.attack_percent() / 100;
                    result.max_attack += result.max_attack * dragon.attack_percent() / 100;
                    result.min_magic += result.min_magic * dragon.magic_percent() / 100;
                    result.max_magic += result.max_magic * dragon.magic_percent() / 100;
                    result.weapon_min_attack +=
                        result.weapon_min_attack * dragon.attack_percent() / 100;
                    result.weapon_max_attack +=
                        result.weapon_max_attack * dragon.attack_percent() / 100;
                    result.weapon_min_magic +=
                        result.weapon_min_magic * dragon.magic_percent() / 100;
                    result.weapon_max_magic +=
                        result.weapon_max_magic * dragon.magic_percent() / 100;
                    if (gear.item->range > 0) {
                        result.attack_range = gear.item->range;
                    }
                    if (gear.item->attack_speed_ms > 0) {
                        result.attack_speed_ms = gear.item->attack_speed_ms;
                    }
                }
            }
            for (const auto& gear : worn) {
                if (!gear.prefix) {
                    continue;
                }
                gear.prefix->apply_derived(result.hit,
                                           result.min_attack,
                                           result.max_attack,
                                           result.min_magic,
                                           result.max_magic,
                                           result.defense,
                                           result.absorb,
                                           result.res_fire,
                                           result.res_ice,
                                           result.res_lightning,
                                           result.res_curse,
                                           result.res_palsy);
                result.defense_range += gear.prefix->defense;
            }
            result.defense += random_defense_points;
            result.defense_range += random_defense_points;
            if (fanta_attack_add != 0) {
                result.min_attack += fanta_attack_add;
                result.max_attack += fanta_attack_add;
                result.min_magic += fanta_attack_add;
                result.max_magic += fanta_attack_add;
                result.weapon_min_attack += fanta_attack_add;
                result.weapon_max_attack += fanta_attack_add;
                result.weapon_min_magic += fanta_attack_add;
                result.weapon_max_magic += fanta_attack_add;
            }
            if (bof_bonus.defense_percent() != 0) {
                result.defense += result.defense * bof_bonus.defense_percent() / 100;
                result.defense_range += result.defense_range * bof_bonus.defense_percent() / 100;
            }
            result.defense += c.skill_buffs.aura_defense_points();
            result.defense_range += c.skill_buffs.aura_range_defense_points();
            result.fatal_rate += c.skill_buffs.blessing_critical_points();

            // Apply class effects, accumulated percentages, food, and curses.
            if (c.clazz == combat::kPcKnight) {
                const int weapon_mastery_level = learned_skill_level(c, 2);
                if (weapon_mastery_level > 0) {
                    const auto mastery =
                        combat::knight_weapon_mastery_contribution(weapon_mastery_level);
                    result.hit += mastery.hit;
                    result.min_attack += mastery.min_attack;
                    result.max_attack += mastery.max_attack;
                }
                const int critical_level = learned_skill_level(c, 12);
                if (critical_level > 0) {
                    const auto critical = combat::knight_critical_contribution(critical_level);
                    result.fatal_pt += critical.fatal_pt;
                    result.fatal_rate += critical.fatal_rate;
                }
                if (learned_skill_level(c, 36) > 0) {
                    result.fatal_pt += combat::knight_advanced_critical_fatal_pt();
                }

                result.hit += c.skill_buffs.accuracy_chant_points();
                const int battle_attack = c.skill_buffs.battle_chant_attack_points();
                result.min_attack += battle_attack;
                result.max_attack += battle_attack;
                const int berserk_attack = c.skill_buffs.berserk_attack_percent();
                result.min_attack += result.min_attack * berserk_attack / 100;
                result.max_attack += result.max_attack * berserk_attack / 100;

                if (learned_skill_level(c, 39) > 0) {
                    const int org_defense = result.defense;
                    const std::int32_t extra =
                        combat::knight_defense_strengthening_points(c.level, org_defense);
                    result.defense += extra;
                    result.defense_range += extra;
                }
                result.defense += result.defense * c.skill_buffs.force_defense_percent() / 100;
                result.defense_range +=
                    result.defense_range * c.skill_buffs.force_range_defense_percent() / 100;
                result.defense += result.defense * c.skill_buffs.defense_chant_percent() / 100;
                result.defense_range +=
                    result.defense_range * c.skill_buffs.defense_chant_range_percent() / 100;
                const int berserk_defense = c.skill_buffs.berserk_defense_percent();
                result.defense += result.defense * berserk_defense / 100;
                result.defense_range += result.defense_range * berserk_defense / 100;
                result.defense += c.skill_buffs.elastic_shield_defense_points();
                result.defense_range += c.skill_buffs.elastic_shield_range_defense_points();
                const int blessing_rank =
                    std::max(learned_skill_level(c, 70), learned_skill_level(c, 71));
                const int blessing_percent = combat::knight_blessing_power_percent(blessing_rank);
                if (blessing_percent > 0) {
                    result.min_attack += result.min_attack * blessing_percent / 100;
                    result.max_attack += result.max_attack * blessing_percent / 100;
                    result.min_magic += result.min_magic * blessing_percent / 100;
                    result.max_magic += result.max_magic * blessing_percent / 100;
                }
                result.res_lightning += c.skill_buffs.lightning_chant_resistance();
                result.res_ice += c.skill_buffs.ice_chant_resistance();
                result.res_fire += c.skill_buffs.flame_chant_resistance();
                result.block_percent += learned_skill_level(c, combat::kKnightDefenseSkill);
                if (learned_skill_level(c, combat::kKnightWeaponDefendSkill) > 0) {
                    result.block_percent += combat::knight_weapon_defend_block(c.level);
                }
            } else if (c.clazz == combat::kPcArcher) {
                const auto mastery =
                    combat::archer_bow_mastery_contribution(learned_skill_level(c, 2));
                result.min_attack += mastery.min_attack;
                result.max_attack += mastery.max_attack;
                result.hit += combat::archer_concentration_hit(learned_skill_level(c, 5));

                const auto evasion = combat::archer_evasion_contribution(
                    learned_skill_level(c, 8), learned_skill_level(c, 20));
                result.perfect_evasion_base = evasion.base_percent;
                result.perfect_evasion_advanced = evasion.advanced_percent;

                const auto fatal = combat::archer_fatal_contribution(
                    learned_skill_level(c, 12), learned_skill_level(c, 32) > 0);
                result.fatal_pt += fatal.fatal_pt + fatal.advanced_fatal_pt;
                result.fatal_rate += fatal.fatal_rate;
                result.attack_range +=
                    combat::archer_attack_range_bonus(learned_skill_level(c, 17));

                result.fatal_rate += c.skill_buffs.archer_chance_capture_fatal_rate();
                result.hit += c.skill_buffs.archer_chance_capture_hit();
                result.min_attack += c.skill_buffs.archer_muscle_min_attack();
                result.res_lightning += c.skill_buffs.archer_lightning_resistance();
                result.res_ice += c.skill_buffs.archer_ice_resistance();
                result.res_fire += c.skill_buffs.archer_fire_resistance();
                result.res_curse += c.skill_buffs.archer_curse_resistance();
                result.res_palsy += c.skill_buffs.archer_spirit_resistance();
                if (learned_skill_level(c, 48) > 0) {
                    result.dodge += combat::archer_shrewdness_dodge_points(result.dodge, c.level);
                }
                const int blessing_rank =
                    std::max(learned_skill_level(c, 70), learned_skill_level(c, 71));
                const int blessing_percent = combat::archer_blessing_power_percent(blessing_rank);
                if (blessing_percent > 0) {
                    result.min_attack += result.min_attack * blessing_percent / 100;
                    result.max_attack += result.max_attack * blessing_percent / 100;
                    result.min_magic += result.min_magic * blessing_percent / 100;
                    result.max_magic += result.max_magic * blessing_percent / 100;
                }
            } else if (c.clazz == combat::kPcThief) {
                const int attack_level = learned_skill_level(c, 2);
                result.min_attack += attack_level;
                result.max_attack += attack_level;
                result.hit += 2 * learned_skill_level(c, 3);
                result.fatal_rate += learned_skill_level(c, 4);
                result.fatal_pt += learned_skill_level(c, 5);
                result.fatal_rate += learned_skill_level(c, 37);
                result.hit += c.skill_buffs.value(SkillBuffId::ThiefDualShadow);
                result.dodge += c.skill_buffs.value(SkillBuffId::ThiefDualShadow, true);
                result.dodge += c.skill_buffs.value(SkillBuffId::ThiefWindCry);
            }
            // Apply the per-instance percentage modifiers once after every flat
            // equipment, prefix, mix, and class contribution has accumulated.
            // This prevents multiple armor parts from compounding each other.
            const auto apply_accumulated_percent = [](std::int32_t& stat, int percent) {
                stat = combat::clamp_nonneg_i32(static_cast<std::int64_t>(stat) +
                                                static_cast<std::int64_t>(stat) * percent / 100);
            };
            apply_accumulated_percent(result.min_attack, random_min_attack_percent);
            apply_accumulated_percent(result.max_attack, random_max_attack_percent);
            apply_accumulated_percent(result.min_magic, random_min_magic_percent);
            apply_accumulated_percent(result.max_magic, random_max_magic_percent);
            apply_accumulated_percent(result.weapon_min_attack, random_min_attack_percent);
            apply_accumulated_percent(result.weapon_max_attack, random_max_attack_percent);
            apply_accumulated_percent(result.weapon_min_magic, random_min_magic_percent);
            apply_accumulated_percent(result.weapon_max_magic, random_max_magic_percent);
            apply_accumulated_percent(result.defense, random_defense_percent);
            apply_accumulated_percent(result.defense_range, random_defense_percent);
            const int food_attack =
                c.pay_buffs.percent_of(static_cast<int>(protocol::BuffType::AttackFood));
            const int food_magic =
                c.pay_buffs.percent_of(static_cast<int>(protocol::BuffType::MagicAttackFood));
            apply_accumulated_percent(result.min_attack, food_attack);
            apply_accumulated_percent(result.max_attack, food_attack);
            apply_accumulated_percent(result.weapon_min_attack, food_attack);
            apply_accumulated_percent(result.weapon_max_attack, food_attack);
            apply_accumulated_percent(result.min_magic, food_magic);
            apply_accumulated_percent(result.max_magic, food_magic);
            apply_accumulated_percent(result.weapon_min_magic, food_magic);
            apply_accumulated_percent(result.weapon_max_magic, food_magic);
            std::int32_t curse_value1 = 0;
            std::int32_t curse_value2 = 0;
            if (c.skill_buffs.values(
                    SkillBuffId::ArcherCurseCritical, curse_value1, curse_value2)) {
                result.fatal_rate = std::max<std::int32_t>(0, result.fatal_rate + curse_value1);
            }
            if (c.skill_buffs.values(SkillBuffId::ArcherCurseDefense, curse_value1, curse_value2)) {
                result.defense = combat::clamp_nonneg_i32(
                    static_cast<std::int64_t>(result.defense) +
                    static_cast<std::int64_t>(result.defense) * curse_value1 / 100);
                result.defense_range = combat::clamp_nonneg_i32(
                    static_cast<std::int64_t>(result.defense_range) +
                    static_cast<std::int64_t>(result.defense_range) * curse_value2 / 100);
            }
            const std::int32_t hit_percent = c.skill_buffs.archer_hit_percent();
            if (hit_percent != 0) {
                result.hit = combat::clamp_nonneg_i32(static_cast<std::int64_t>(result.hit) +
                                                      static_cast<std::int64_t>(result.hit) *
                                                          hit_percent / 100);
            }
            result.attack_speed_ms = combat::revised_attack_delay_ms(
                result.attack_speed_ms, c.skill_buffs.archer_attack_speed_percent());
            result.attack_range = std::max(
                0, result.attack_range + static_cast<int>(c.skill_buffs.archer_range_delta()));
            if (result.max_attack < result.min_attack) {
                std::swap(result.min_attack, result.max_attack);
            }

            // Derive resources and resistance, then clamp current resources.
            // Char::ReviseProperty + compatibility behavior HP/MP bases.
            result.max_hp = combat::max_hp_from_stats(stats.hth, c.level, c.clazz);
            result.max_mp = combat::max_mp_from_stats(stats.wis, c.level, c.clazz);
            for (const auto& gear : worn) {
                if (gear.item) {
                    result.max_hp += gear.item->hp;
                    result.max_mp += gear.item->mp;
                }
                if (gear.prefix) {
                    result.max_hp += gear.prefix->hp;
                    result.max_mp += gear.prefix->mp;
                }
                const QigongBonus qigong = QigongBonus::from_effect(
                    gear.qigong_effect,
                    gear.item && gear.item->is_weapon,
                    gear.item ? gear.item->class_small : std::string_view{});
                result.max_hp += qigong.hp();
                result.max_mp += qigong.mp();
                const DragonFusingBonus dragon = DragonFusingBonus::from_effect(
                    gear.dragon_effect,
                    gear.item && gear.item->is_weapon,
                    gear.item ? gear.item->class_small : std::string_view{});
                result.max_hp += dragon.hp();
                result.max_mp += dragon.mp();
            }

            // Apply mix flat and percent HP/MP additions (PutOn()).
            result.max_hp += mix_hp_flat_add;
            result.max_mp += mix_mp_flat_add;
            if (mix_hp_pct_add != 0) {
                result.max_hp += result.max_hp * mix_hp_pct_add / 100;
            }
            if (mix_mp_pct_add != 0) {
                result.max_mp += result.max_mp * mix_mp_pct_add / 100;
            }
            if (bof_bonus.hp_mp_percent() != 0) {
                result.max_hp += result.max_hp * bof_bonus.hp_mp_percent() / 100;
                result.max_mp += result.max_mp * bof_bonus.hp_mp_percent() / 100;
            }
            if (c.clazz == combat::kPcMage) {
                const auto life_extension = c.learned_skills.find(30);
                if (life_extension != c.learned_skills.end()) {
                    const int percent =
                        protocol::mage_life_extension_percent(life_extension->second);
                    result.max_hp += result.max_hp * percent / 100;
                }
            } else if (c.clazz == combat::kPcKnight) {
                const int life_extension_level = learned_skill_level(c, 30);
                if (life_extension_level > 0) {
                    const std::int32_t revised_hth_hp = std::max<std::int32_t>(
                        0, combat::max_hp_from_stats(stats.hth, 0, c.clazz) - 115);
                    result.max_hp +=
                        combat::knight_life_extension_hp(revised_hth_hp, life_extension_level);
                }
            } else if (c.clazz == combat::kPcArcher) {
                const int life_extension_level = learned_skill_level(c, 30);
                if (life_extension_level > 0) {
                    result.max_hp += combat::archer_life_extension_hp(result.base_stats.hth,
                                                                      life_extension_level);
                }
            } else if (c.clazz == combat::kPcThief) {
                const int life_extension_level = learned_skill_level(c, 30);
                if (life_extension_level > 0) {
                    result.max_hp += result.max_hp * (14 + 10 * life_extension_level) / 100;
                }
                result.max_hp += result.max_hp * c.skill_buffs.value(SkillBuffId::ThiefWrath) / 100;
            }
            if (bof_bonus.resist_percent() != 0) {
                result.res_fire += result.res_fire * bof_bonus.resist_percent() / 100;
                result.res_ice += result.res_ice * bof_bonus.resist_percent() / 100;
                result.res_lightning += result.res_lightning * bof_bonus.resist_percent() / 100;
                result.res_curse += result.res_curse * bof_bonus.resist_percent() / 100;
                result.res_palsy += result.res_palsy * bof_bonus.resist_percent() / 100;
            }
            if (c.mounted) {
                const ClientSession::BagSlot* battle_ride = nullptr;
                for (const auto& slot : c.bag) {
                    const auto riding = world.riding_defs().find(slot.index);
                    if (slot.equipped && slot.count > 0 && riding != world.riding_defs().end() &&
                        riding->second.kind == protocol::RidingKind::Battle) {
                        battle_ride = &slot;
                        break;
                    }
                }
                const auto mount =
                    battle_ride ? c.battle_mounts.find(battle_ride->iid) : c.battle_mounts.end();
                if (mount != c.battle_mounts.end()) {
                    constexpr std::array<int, 4> kPrimaryBase{1, 12, 24, 35};
                    constexpr std::array<int, 4> kSecondaryBase{1, 6, 12, 17};
                    for (std::int32_t equipment_iid : mount->second.equipment_iids) {
                        const ClientSession::BagSlot* equipment = nullptr;
                        for (const auto& slot : c.bag) {
                            if (slot.iid == static_cast<std::uint32_t>(equipment_iid)) {
                                equipment = &slot;
                                break;
                            }
                        }
                        if (!equipment || equipment->index < 30200 || equipment->index > 30223) {
                            continue;
                        }
                        const int offset = equipment->index - 30200;
                        const int grade = std::clamp(offset / 6, 0, 3);
                        const int type_index = offset % 6;
                        const int base =
                            type_index >= 4 ? kSecondaryBase[grade] : kPrimaryBase[grade];
                        const int value = battle_riding_satiety_scaled_value(
                            base + std::clamp(equipment->upgrade_level, 0, 10),
                            mount->second.satiety,
                            mount->second.max_satiety);
                        if (type_index == 0) {
                            result.min_attack += value;
                            result.max_attack += value;
                        } else if (type_index == 1) {
                            result.min_magic += value;
                            result.max_magic += value;
                        } else if (type_index == 2) {
                            result.defense += value;
                            result.defense_range += value;
                        } else if (type_index == 3) {
                            result.max_hp += value;
                        } else if (type_index == 4) {
                            result.defense_range += value;
                        } else if (type_index == 5) {
                            result.dodge += value;
                        }
                    }
                }
            }
            result.max_hp += collection.hp;
            result.max_mp += collection.mp;
            result.max_hp += static_cast<int>(result.max_hp * collection.ability[10] / 100.0);
            result.max_mp += static_cast<int>(result.max_mp * collection.ability[11] / 100.0);
            if (result.max_hp < 1) {
                result.max_hp = 1;
            }
            if (result.max_mp < 1) {
                result.max_mp = 1;
            }
            const auto talents = protocol::talent_bonuses(c.talent_mask);
            result.max_mp =
                std::max(1, (result.max_mp + talents.mana) * (100 + talents.mana_percent) / 100);
            // Cap current to max (level-up / buff loss); do not revive from 0.
            if (result.cur_hp > result.max_hp) {
                result.cur_hp = result.max_hp;
            }
            if (result.cur_hp < 0) {
                result.cur_hp = 0;
            }
            if (result.cur_mp > result.max_mp) {
                result.cur_mp = result.max_mp;
            }
            if (result.cur_mp < 0) {
                result.cur_mp = 0;
            }

            // Apply form, collection, talents, and final guild modifiers.
            result.weapon_wear = static_cast<std::uint16_t>(c.weapon_index);
            // Cloth slots: openkal maps upper armor into wear[3] (IC_ARMOR / part A).
            result.armor_wear = static_cast<std::uint16_t>(c.armor_index);
            result.transform_mspeed_percent = 0;
            if (c.transform_stage >= protocol::kTransLvBaby && c.transform.index > 0) {
                const ItemCombatDef* egg = item_def_of(world, c.transform.index);
                if (egg && egg->is_transform) {
                    const auto form =
                        protocol::form_transform_bonus(egg->transform_race, c.transform_stage);
                    result.transform_mspeed_percent = form.mspeed_percent;
                    if (form.attack_percent != 0) {
                        result.min_attack += result.min_attack * form.attack_percent / 100;
                        result.max_attack += result.max_attack * form.attack_percent / 100;
                    }
                    if (form.magic_percent != 0) {
                        result.min_magic += result.min_magic * form.magic_percent / 100;
                        result.max_magic += result.max_magic * form.magic_percent / 100;
                    }
                    if (form.defense_min != 0 || form.defense_max != 0) {
                        const int def_add = (form.defense_min + form.defense_max) / 2;
                        result.defense += def_add;
                        result.defense_range += def_add;
                    }
                }
            }
            result.min_attack += collection.attack;
            result.max_attack += collection.attack;
            result.min_magic += collection.attack;
            result.max_magic += collection.attack;
            result.min_attack +=
                static_cast<int>(result.min_attack * collection.ability[13] / 100.0);
            result.max_attack +=
                static_cast<int>(result.max_attack * collection.ability[14] / 100.0);
            result.min_magic += static_cast<int>(result.min_magic * collection.ability[18] / 100.0);
            result.max_magic += static_cast<int>(result.max_magic * collection.ability[19] / 100.0);
            result.hit += static_cast<int>(collection.ability[5]);
            result.dodge += static_cast<int>(collection.ability[6]);
            result.defense += static_cast<int>(collection.ability[7]);
            result.defense_range += static_cast<int>(collection.ability[7]);
            result.res_fire += static_cast<int>(collection.ability[8]);
            result.res_ice += static_cast<int>(collection.ability[8]);
            result.res_lightning += static_cast<int>(collection.ability[8]);
            result.res_curse += static_cast<int>(collection.ability[8]);
            result.res_palsy += static_cast<int>(collection.ability[8]);
            result.absorb += static_cast<int>(collection.ability[9]);
            result.fatal_rate += static_cast<int>(collection.ability[15]);
            result.min_attack = std::max(0, result.min_attack + talents.physical);
            result.max_attack =
                std::max(0, result.max_attack + talents.physical + talents.max_physical);
            result.min_attack = std::min(result.min_attack, result.max_attack);
            result.min_magic = std::max(0, result.min_magic + talents.magical);
            result.max_magic = std::max(result.min_magic, result.max_magic + talents.magical);
            result.defense = std::max(0, result.defense + talents.defense);
            result.defense_range = std::max(0, result.defense_range + talents.defense);
            result.dodge = std::max(0, result.dodge + talents.evasion);
            result.max_hp =
                combat::clamp_nonneg_i32(static_cast<std::int64_t>(result.max_hp) + guild_bonus[1]);
            result.cur_hp = std::min(result.cur_hp, result.max_hp);
            result.defense = combat::clamp_nonneg_i32(static_cast<std::int64_t>(result.defense) +
                                                      guild_bonus[2]);
            result.defense_range = combat::clamp_nonneg_i32(
                static_cast<std::int64_t>(result.defense_range) + guild_bonus[2]);
            result.gstate = protocol::pack_bof_gstate(
                result.gstate, bof_bonus.completeness(), bof_bonus.fx_level());

            return result;
        }

        /** Commits one completed calculation without touching other session state. */
        void
        apply_combat_result(ClientSession& c, const CombatResult& result, const GameWorld& world) {
            c.collection_world = &world;
            c.str = result.base_stats.str;
            c.hth = result.base_stats.hth;
            c.intl = result.base_stats.intl;
            c.wis = result.base_stats.wis;
            c.dex = result.base_stats.dex;
            c.stats_initialized = true;
            c.collection_bonus = result.collection_bonus;
            c.prefix_bonus = result.prefix_bonus;
            c.min_attack = result.min_attack;
            c.max_attack = result.max_attack;
            c.min_magic = result.min_magic;
            c.max_magic = result.max_magic;
            c.hit = result.hit;
            c.dodge = result.dodge;
            c.defense = result.defense;
            c.defense_range = result.defense_range;
            c.absorb = result.absorb;
            c.fatal_rate = result.fatal_rate;
            c.fatal_pt = result.fatal_pt;
            c.perfect_evasion_base = result.perfect_evasion_base;
            c.perfect_evasion_advanced = result.perfect_evasion_advanced;
            c.block_percent = result.block_percent;
            c.wearing_shield = result.wearing_shield;
            c.wearing_two_hand = result.wearing_two_hand;
            c.upgrade_level = result.upgrade_level;
            c.char_attack = result.char_attack;
            c.char_magic = result.char_magic;
            c.weapon_min_attack = result.weapon_min_attack;
            c.weapon_max_attack = result.weapon_max_attack;
            c.weapon_min_magic = result.weapon_min_magic;
            c.weapon_max_magic = result.weapon_max_magic;
            c.res_fire = result.res_fire;
            c.res_ice = result.res_ice;
            c.res_lightning = result.res_lightning;
            c.res_curse = result.res_curse;
            c.res_palsy = result.res_palsy;
            c.attack_range = result.attack_range;
            c.attack_speed_ms = result.attack_speed_ms;
            c.max_hp = result.max_hp;
            c.max_mp = result.max_mp;
            c.cur_hp = result.cur_hp;
            c.cur_mp = result.cur_mp;
            c.transform_mspeed_percent = result.transform_mspeed_percent;
            c.gstate = result.gstate;
            c.wear[0] = result.weapon_wear;
            c.wear[3] = result.armor_wear;
        }

        void recompute_combat(ClientSession& c, const GameWorld& world) {
            const auto result = calculate_combat(capture_combat_inputs(c, world, c.collection_pve));
            apply_combat_result(c, result, world);
        }

        /** Broadcasts S2C_ACTION AT_REST for `c` to every playing session. */
        void broadcast_rest_action(const ClientSession& c, std::vector<ClientSession>& clients) {
            const auto act = protocol::Skill::frame_action_rest(c.player_id, c.resting ? 1 : 0);
            for (auto& peer : clients) {
                if (peer.phase == SessionPhase::Playing && peer.sock) {
                    peer.sock->enqueue(act);
                }
            }
        }

        /** Broadcasts S2C_MSTATE in sight (compatibility behavior / SubMState). */
        void broadcast_mstate(const ClientSession& c, std::vector<ClientSession>& clients) {
            const auto pkt = protocol::MState::frame(c.player_id, c.rest_food.mstate());
            for (auto& peer : clients) {
                if (peer.phase == SessionPhase::Playing && peer.sock &&
                    same_map_in_sight(peer.map, peer.px, peer.py, c.map, c.px, c.py)) {
                    peer.sock->enqueue(pkt);
                }
            }
        }

        /** Broadcasts S2C_EFFECT in sight (compatibility behavior WriteInRect). */
        void broadcast_effect(const ClientSession& c,
                              std::vector<ClientSession>& clients,
                              std::uint8_t effect) {
            if (effect == 0) {
                return;
            }
            const auto pkt = protocol::Effect::frame(c.player_id, effect);
            for (auto& peer : clients) {
                if (peer.phase == SessionPhase::Playing && peer.sock &&
                    same_map_in_sight(peer.map, peer.px, peer.py, c.map, c.px, c.py)) {
                    peer.sock->enqueue(pkt);
                }
            }
        }

        /**
         * Clears sit HP/MP food (related compatibility states).
         * @param c Session to update.
         * @param clients Sight broadcast list.
         */
        void cancel_rest_food(ClientSession& c, std::vector<ClientSession>& clients) {
            if (!c.rest_food.active()) {
                return;
            }
            c.rest_food.cancel_all();
            broadcast_mstate(c, clients);
        }

        /** Ends sitting and its consumables, and synchronizes the standing pose.
         * @param c Session to update.
         * @param clients Sight broadcast list.
         */
        void stand_player(ClientSession& c, std::vector<ClientSession>& clients) {
            cancel_rest_food(c, clients);
            if (c.resting) {
                c.resting = false;
                broadcast_rest_action(c, clients);
            }
        }

        /**
         * Applies compatibility behavior. Sit arms the 5s first pulse and clears compatibility
         * behavior.
         * @param c Session to update.
         * @param clients Sight broadcast list.
         * @param want True to sit.
         * @param now_ms Monotonic milliseconds.
         */
        void apply_player_rest(ClientSession& c,
                               std::vector<ClientSession>& clients,
                               bool want,
                               std::uint64_t now_ms) {
            if (!want) {
                stand_player(c, clients);
                return;
            }
            if (c.resting) {
                return;
            }
            c.resting = true;
            c.boosting = false;
            c.walking_on_air = false;
            c.next_sit_regen_ms = player_regen::sit_first_due_ms(now_ms);
            broadcast_rest_action(c, clients);
        }

        /** Sends a single-word property update to the owning client. */
        void send_cur_property(ClientSession& c, protocol::PropertyType type, std::int32_t value) {
            if (!c.sock) {
                return;
            }
            c.sock->enqueue(protocol::Property::frame_update(static_cast<std::uint8_t>(type),
                                                             combat::clamp_nonneg_i32(value)));
        }

        /** @return Learned level for a skill index, or 0. */
        [[nodiscard]] int learned_skill_level(const ClientSession& c, int index) {
            const auto it = c.learned_skills.find(index);
            return it == c.learned_skills.end() ? 0 : it->second;
        }

        /**
         * Syncs compatibility behavior passive points (compatibility behavior → runtime state =
         * skill level).
         * @param c Session to update.
         */
        void sync_rest_point(ClientSession& c) {
            c.rest_point = learned_skill_level(c, 11);
        }

        /** Resolves the bag iid for an item definition index (SP uses the index when empty).
         */
        [[nodiscard]] std::uint32_t bag_iid_for_index(const ClientSession& c, int index) {
            for (const auto& slot : c.bag) {
                if (slot.iid != 0 && slot.index == index) {
                    return slot.iid;
                }
            }
            return static_cast<std::uint32_t>(std::max(0, index));
        }

        void send_rage(ClientSession& c) {
            if (!c.sock) {
                return;
            }
            c.sock->enqueue(protocol::Property::frame_update(protocol::kPropertyRage, c.rage));
        }

        void send_mortal(ClientSession& c) {
            if (!c.sock) {
                return;
            }
            c.sock->enqueue(protocol::Property::frame_update(protocol::kPropertyMortal, c.mortal));
        }

        void add_mortal(ClientSession& c, int amount) {
            c.mortal = std::clamp(c.mortal + amount, 0, 5);
            send_mortal(c);
        }

        void cancel_hiding(ClientSession& c, const GameWorld& world) {
            const std::uint64_t cleared = c.skill_buffs.remove(SkillBuffId::ThiefHiding);
            if (cleared == 0) {
                return;
            }
            send_sub_bstate(c, cleared);
            recompute_combat(c, world);
            sync_skill_buff_stats(c);
        }

        void send_system_mail_list(IDataStore* store, ClientSession& c);
        const SkillDef* find_skill_def(const GameWorld& world, int clazz, int index);
        [[nodiscard]] int
        skill_cast_range(const SkillDef& def, int skill_level, int fallback_range);
        void begin_combat_corpse(MonsterEntity& m);
        void broadcast_known_monster(std::vector<ClientSession>& clients,
                                     std::uint32_t id,
                                     const std::vector<std::uint8_t>& pkt);
        struct MonsterRewardResult {
            ClientSession* drop_owner = nullptr;
            std::uint32_t owner_party_id = 0;
            MonsterLootAccess loot_access = MonsterLootAccess::None;
        };

        MonsterRewardResult
        allot_monster_kill_exp(const MonsterEntity* monster,
                               const MonsterDef* def,
                               std::vector<ClientSession>& clients,
                               const GameWorld& world,
                               IDataStore* store,
                               const LevelMailRewardCatalog* level_mail_rewards = nullptr);
