        /** Pushes one bag egg's level/EXP (compatibility behavior nNum / byMaxEnd). */
        void send_transform_item_info_from_slot(ClientSession& c,
                                                const ClientSession::BagSlot& slot,
                                                int added = 0) {
            if (!c.sock || slot.iid == 0) {
                return;
            }
            protocol::UpdateItemInfoFields fields;
            fields.iid = slot.iid;
            fields.index = static_cast<std::uint16_t>(std::max(0, slot.index));
            const int level = slot.transform_level < 1 ? 1 : slot.transform_level;
            fields.level = static_cast<std::uint8_t>(std::clamp(level, 1, 255));
            fields.exp = static_cast<std::uint32_t>(std::max(0, slot.transform_exp));
            fields.added = static_cast<std::uint16_t>(std::max(0, added));
            c.sock->enqueue(protocol::ItemInfo::frame_update(fields));
        }

        /** Pushes the worn egg's level/EXP so the H-window, HUD, and bag stay in sync. */
        void send_transform_item_info(ClientSession& c, int added = 0) {
            sync_transform_progress_to_equipped_item(c);
            if (!c.sock || c.transform.index <= 0) {
                return;
            }
            for (const auto& slot : c.bag) {
                if (slot.equipped && slot.index == c.transform.index && slot.iid != 0) {
                    send_transform_item_info_from_slot(c, slot, added);
                    return;
                }
            }
            protocol::UpdateItemInfoFields fields;
            fields.iid = bag_iid_for_index(c, c.transform.index);
            fields.index = static_cast<std::uint16_t>(std::max(0, c.transform.index));
            fields.level = static_cast<std::uint8_t>(std::clamp(c.transform.level, 1, 255));
            fields.exp = static_cast<std::uint32_t>(std::max(0, c.transform.exp));
            fields.added = static_cast<std::uint16_t>(std::max(0, added));
            c.sock->enqueue(protocol::ItemInfo::frame_update(fields));
        }

        void add_rage(ClientSession& c, int amount) {
            if (amount == 0) {
                return;
            }
            c.rage = std::clamp(c.rage + amount, 0, protocol::max_rage());
            send_rage(c);
        }

        void broadcast_transform_action(std::vector<ClientSession>& clients,
                                        const std::vector<std::uint8_t>& pkt) {
            for (auto& peer : clients) {
                if (peer.phase == SessionPhase::Playing && peer.sock) {
                    peer.sock->enqueue(pkt);
                }
            }
        }

        ClientSession::BagSlot* registered_ride(ClientSession& c, const GameWorld& world) {
            for (auto& slot : c.bag) {
                if (!slot.equipped || slot.count <= 0 || slot.index <= 0) {
                    continue;
                }
                const auto def = world.riding_defs().find(slot.index);
                if (def != world.riding_defs().end()) {
                    return &slot;
                }
            }
            return nullptr;
        }

        const RidingDef* registered_ride_def(ClientSession& c, const GameWorld& world) {
            const ClientSession::BagSlot* slot = registered_ride(c, world);
            if (!slot) {
                return nullptr;
            }
            const auto it = world.riding_defs().find(slot->index);
            return it == world.riding_defs().end() ? nullptr : &it->second;
        }

        [[nodiscard]] double
        allowed_player_move_speed(ClientSession& c, const GameWorld& world, bool rushing) {
            if (c.walking_on_air) {
                return protocol::kWalkOnAirSpeed;
            }
            const auto* ride = c.mounted ? registered_ride_def(c, world) : nullptr;
            const int form_speed = ride ? ride->movement_speed_percent : c.transform_mspeed_percent;
            const int property_speed =
                std::clamp(form_speed + static_cast<int>(c.collection_bonus.ability[12]) +
                               protocol::talent_bonuses(c.talent_mask).speed_percent,
                           ride ? 0 : -100,
                           300);
            // Match the speed modifiers the client applies to local movement.
            int percent = property_speed + c.skill_buffs.haste_mspeed_percent();
            if (c.skill_buffs.find(SkillBuffId::ArcherEscape)) {
                percent += protocol::kArcherEscapeMoveSpeedPercent;
            }
            if (c.skill_buffs.find(SkillBuffId::ArcherSharpness)) {
                percent += protocol::kArcherSharpnessMoveSpeedPercent;
            }
            if (c.skill_buffs.find(SkillBuffId::ThiefHiding)) {
                percent += protocol::kThiefHidingMoveSpeedPercent;
            }
            if (rushing) {
                percent += 300;
            }
            return protocol::kRunSpeed * protocol::move_speed_factor(static_cast<std::int16_t>(
                                             std::clamp(percent, -99, 300)));
        }

        [[nodiscard]] bool
        combat_repeat_ready(std::uint64_t now, std::uint64_t deadline, int interval_ms) {
            // Allow arrival jitter. Advancing from the later of now and the previous
            // deadline prevents the same allowance from shortening every repeat.
            const auto grace_ms = static_cast<std::uint64_t>(std::min(120, interval_ms / 2));
            return now + grace_ms >= deadline;
        }

        [[nodiscard]] int
        skill_icon_cooldown_ms(const SkillDef& def, int rank, int weapon_speed_ms) {
            if (!def.cooldown_by_level.empty()) {
                const auto level =
                    std::clamp(rank, 1, static_cast<int>(def.cooldown_by_level.size()));
                return def.cooldown_by_level[level - 1];
            }
            if (def.compare_cooldown_weapon_speed) {
                return weapon_speed_ms + std::max(0, def.compare_cooldown_ms);
            }
            return def.compare_cooldown_ms;
        }

        [[nodiscard]] int pve_weapon_range(const ClientSession& c) {
            const int fallback = c.clazz == combat::kPcArcher ? 160 : 16;
            return c.attack_range > 16 ? c.attack_range : fallback;
        }

        BattleMountRecord* ensure_battle_mount(ClientSession& c,
                                               const ClientSession::BagSlot& slot,
                                               const RidingDef& definition,
                                               IDataStore* store) {
            if (definition.kind != protocol::RidingKind::Battle || slot.iid == 0) {
                return nullptr;
            }
            const auto found = c.battle_mounts.find(slot.iid);
            if (found != c.battle_mounts.end()) {
                return &found->second;
            }
            BattleMountRecord mount;
            if (store) {
                if (const auto loaded =
                        store->load_battle_mount(static_cast<std::int32_t>(slot.iid))) {
                    mount = *loaded;
                }
            }
            if (mount.mount_iid == 0) {
                mount.mount_iid = static_cast<std::int32_t>(slot.iid);
                mount.grade = definition.initial_grade;
                if (store && !store->upsert_battle_mount(mount)) {
                    log::warn("ServerHost: failed to initialize Battle Riding state for iid=" +
                              std::to_string(slot.iid));
                }
            }
            return &c.battle_mounts.emplace(slot.iid, mount).first->second;
        }

        bool
        battle_riding_skill_permitted(ClientSession& c, const GameWorld& world, int skill_index) {
            if (!c.mounted) {
                return true;
            }
            const ClientSession::BagSlot* slot = registered_ride(c, world);
            if (!slot) {
                return true;
            }
            const auto definition = world.riding_defs().find(slot->index);
            if (definition == world.riding_defs().end() ||
                definition->second.kind != protocol::RidingKind::Battle) {
                return true;
            }
            const auto mount = c.battle_mounts.find(slot->iid);
            const protocol::BattleRidingGrade grade = mount == c.battle_mounts.end()
                                                          ? definition->second.initial_grade
                                                          : mount->second.grade;
            return battle_riding_skill_allowed(grade, c.clazz, skill_index);
        }

        void broadcast_riding_state(ClientSession& c,
                                    std::vector<ClientSession>& clients,
                                    const GameWorld& world) {
            protocol::RidingState state;
            state.player_id = c.player_id;
            if (const ClientSession::BagSlot* slot = registered_ride(c, world)) {
                state.iid = slot->iid;
                state.item_index = static_cast<std::uint16_t>(slot->index);
                state.expire_at =
                    static_cast<std::uint64_t>(std::max<std::int64_t>(0, slot->ride_expire_at));
                state.mounted = c.mounted;
                const auto definition = world.riding_defs().find(slot->index);
                if (definition != world.riding_defs().end()) {
                    state.kind = definition->second.kind;
                }
                if (state.kind == protocol::RidingKind::Battle) {
                    const auto mount = c.battle_mounts.find(slot->iid);
                    if (mount != c.battle_mounts.end()) {
                        state.grade = mount->second.grade;
                        state.rarity = battle_riding_grade_rarity(mount->second.grade);
                        state.satiety =
                            static_cast<std::uint16_t>(std::clamp(mount->second.satiety, 0, 65535));
                        state.max_satiety = static_cast<std::uint16_t>(
                            std::clamp(mount->second.max_satiety, 0, 65535));
                        state.revision = mount->second.revision;
                        for (std::size_t i = 0; i < mount->second.equipment_iids.size(); ++i) {
                            const std::uint32_t equipment_iid = static_cast<std::uint32_t>(
                                std::max<std::int32_t>(0, mount->second.equipment_iids[i]));
                            state.equipment_iids[i] = equipment_iid;
                            for (const auto& bag_slot : c.bag) {
                                if (bag_slot.iid == equipment_iid) {
                                    state.equipment_item_indices[i] = static_cast<std::uint16_t>(
                                        std::clamp(bag_slot.index, 0, 65535));
                                    state.equipment_enchants[i] = static_cast<std::uint8_t>(
                                        std::clamp(bag_slot.upgrade_level, 0, 10));
                                    break;
                                }
                            }
                        }
                        for (std::size_t i = 0; i < mount->second.abilities.size(); ++i) {
                            state.abilities[i] = static_cast<std::uint16_t>(
                                std::clamp(mount->second.abilities[i], 0, 65535));
                        }
                    }
                }
            }
            const auto packet = protocol::Riding::frame_server_state(state);
            for (auto& peer : clients) {
                if (peer.phase == SessionPhase::Playing && peer.sock &&
                    same_map_in_sight(peer.map, peer.px, peer.py, c.map, c.px, c.py)) {
                    peer.sock->enqueue(packet);
                }
            }
        }

        void consume_battle_riding_satiety(ClientSession& c,
                                           std::vector<ClientSession>& clients,
                                           const GameWorld& world,
                                           IDataStore* store) {
            if (!c.mounted) {
                return;
            }
            const ClientSession::BagSlot* slot = registered_ride(c, world);
            if (!slot) {
                return;
            }
            const auto definition = world.riding_defs().find(slot->index);
            const auto mount = c.battle_mounts.find(slot->iid);
            if (definition == world.riding_defs().end() ||
                definition->second.kind != protocol::RidingKind::Battle ||
                mount == c.battle_mounts.end()) {
                return;
            }
            battle_riding_consume_skill_hit(mount->second);
            if (!store || store->upsert_battle_mount(mount->second)) {
                recompute_combat(c, world);
                broadcast_riding_state(c, clients, world);
            }
        }

        bool set_riding(ClientSession& c,
                        bool mounted,
                        std::vector<ClientSession>& clients,
                        const GameWorld& world) {
            ClientSession::BagSlot* slot = registered_ride(c, world);
            if (mounted) {
                const std::int64_t now = std::chrono::duration_cast<std::chrono::seconds>(
                                             std::chrono::system_clock::now().time_since_epoch())
                                             .count();
                if (!slot || c.cur_hp <= 0 || c.resting || c.boosting || c.walking_on_air ||
                    c.transform_stage != 0 ||
                    (c.gstate &
                     (protocol::kCgsFish | protocol::kCgsCooking | protocol::kCgsOnStall)) != 0 ||
                    (slot->ride_expire_at > 0 && slot->ride_expire_at <= now)) {
                    return false;
                }
            }
            if (c.mounted == mounted) {
                return true;
            }
            c.mounted = mounted;
            recompute_combat(c, world);
            int speed = 0;
            if (mounted && slot) {
                const auto def = world.riding_defs().find(slot->index);
                if (def != world.riding_defs().end()) {
                    speed = def->second.movement_speed_percent;
                }
            }
            if (c.sock) {
                c.sock->enqueue(protocol::Property::frame_update_mproperty(
                    c.player_id,
                    protocol::kPropertyMSpeed,
                    static_cast<std::int16_t>(
                        std::clamp(speed + (static_cast<int>(c.collection_bonus.ability[12]) +
                                            protocol::talent_bonuses(c.talent_mask).speed_percent),
                                   0,
                                   300))));
            }
            broadcast_riding_state(c, clients, world);
            return true;
        }

        void free_transform_form(ClientSession& c,
                                 std::vector<ClientSession>& clients,
                                 const GameWorld& world) {
            if ((c.gstate & protocol::kCgsOnTransform) == 0 && c.transform_stage == 0) {
                c.pending_transform_stage = 0;
                return;
            }
            const int race = protocol::transform_tflag_race(c.tflag);
            c.gstate &= ~protocol::kCgsOnTransform;
            c.transform_stage = 0;
            c.pending_transform_stage = 0;
            c.tflag = protocol::transform_equip_tflag(race);
            c.next_dec_rage_ms = 0;
            const std::uint64_t hide_cleared = c.skill_buffs.remove(SkillBuffId::ThiefHiding);
            if (hide_cleared != 0) {
                send_sub_bstate(c, hide_cleared);
            }
            recompute_combat(c, world);
            const auto pkt = protocol::Transform::frame_action_form(
                c.player_id, static_cast<std::uint8_t>(c.tflag));
            broadcast_transform_action(clients, pkt);
            if (c.sock) {
                c.sock->enqueue(protocol::Property::frame_update_mproperty(
                    c.player_id,
                    protocol::kPropertyMSpeed,
                    static_cast<std::int16_t>(c.transform_mspeed_percent +
                                              c.collection_bonus.ability[12])));
            }
            send_progression_snapshot(c);
        }

        bool apply_transform_form(ClientSession& c,
                                  std::vector<ClientSession>& clients,
                                  const GameWorld& world,
                                  int stage) {
            if (c.transform.index <= 0 ||
                !protocol::transform_stage_unlocked(c.transform.level, stage)) {
                return false;
            }
            const ItemCombatDef* egg = item_def_of(world, c.transform.index);
            if (!egg || !egg->is_transform) {
                return false;
            }
            c.transform_stage = stage;
            c.tflag = protocol::transform_equip_tflag(egg->transform_race) | stage;
            c.gstate |= protocol::kCgsOnTransform;
            c.pending_transform_stage = 0;
            c.next_dec_rage_ms = steady_ms_now() + 5000;
            recompute_combat(c, world);
            const auto pkt = protocol::Transform::frame_action_form(
                c.player_id, static_cast<std::uint8_t>(c.tflag));
            broadcast_transform_action(clients, pkt);
            if (c.sock) {
                c.sock->enqueue(protocol::Property::frame_update_mproperty(
                    c.player_id,
                    protocol::kPropertyMSpeed,
                    static_cast<std::int16_t>(c.transform_mspeed_percent +
                                              c.collection_bonus.ability[12])));
            }
            send_progression_snapshot(c);
            return true;
        }

        void handle_transform_request(ClientSession& c,
                                      std::vector<ClientSession>& clients,
                                      const GameWorld& world,
                                      std::uint8_t flag,
                                      std::uint8_t stage) {
            if (flag == protocol::kTransMFree) {
                free_transform_form(c, clients, world);
                return;
            }
            if (c.resting || (c.gstate & (protocol::kCgsFish | protocol::kCgsCooking |
                                          protocol::kCgsOnStall)) != 0) {
                return;
            }
            if (stage < protocol::kTransLvBaby || stage > protocol::kTransLvAdult) {
                return;
            }
            if (world.grid().has_attr_world_pixel(c.px, c.py, map::kAttrVillage)) {
                if (c.sock) {
                    c.sock->enqueue(
                        frame_message(static_cast<std::uint8_t>(MsgId::NotTransformArea)));
                }
                return;
            }
            bool wearing_standard = false;
            for (const auto& slot : c.bag) {
                if (!slot.equipped) {
                    continue;
                }
                const ItemCombatDef* def = item_def_of(world, slot.index);
                if (def && def->class_small == "standard") {
                    wearing_standard = true;
                    break;
                }
            }
            if (wearing_standard) {
                if (c.sock) {
                    c.sock->enqueue(
                        frame_message(static_cast<std::uint8_t>(MsgId::NotTransformByFlag)));
                }
                return;
            }
            if (c.rage < protocol::need_rage_for_stage(stage)) {
                if (c.sock) {
                    c.sock->enqueue(frame_message(static_cast<std::uint8_t>(MsgId::NotEnoughRage)));
                }
                return;
            }
            if ((c.gstate & protocol::kCgsOnTransform) != 0) {
                if (c.transform_stage == static_cast<int>(stage)) {
                    if (flag == protocol::kTransMPre) {
                        free_transform_form(c, clients, world);
                    }
                    return;
                }
            }
            if (flag == protocol::kTransMPre) {
                c.pending_transform_stage = stage;
                const auto pkt = protocol::Transform::frame_action_pre(
                    c.player_id, static_cast<std::uint8_t>(stage));
                broadcast_transform_action(clients, pkt);
                return;
            }
            if (flag == protocol::kTransMExecute) {
                if (c.pending_transform_stage != stage &&
                    (c.gstate & protocol::kCgsOnTransform) == 0) {
                    return;
                }
                apply_transform_form(c, clients, world, stage);
            }
        }

        void execute_animal_skill(ClientSession& c,
                                  std::vector<ClientSession>& clients,
                                  GameWorld& world,
                                  std::uint8_t skill_idx,
                                  std::uint32_t target_id,
                                  IDataStore* store,
                                  std::atomic<std::uint32_t>& next_iid,
                                  const terrain::FloorField* indoor_geometry) {
            if ((c.gstate & protocol::kCgsOnTransform) == 0 ||
                !protocol::is_animal_skill(skill_idx)) {
                return;
            }
            const int race = protocol::transform_tflag_race(c.tflag);
            const int stage = protocol::transform_tflag_stage(c.tflag);
            const SkillDef* def =
                find_skill_def(world, protocol::animal_skill_class(race), skill_idx);
            if (!def) {
                return;
            }
            if (stage < ((static_cast<int>(skill_idx) - 101) % 3) + 1) {
                return;
            }
            const auto now = steady_ms_now();
            const int repeat_ms =
                std::max(kMinSkillRepeatMs, skill_icon_cooldown_ms(*def, 1, c.attack_speed_ms));
            auto& ready = c.skill_repeat_ms[skill_idx];
            if (!combat_repeat_ready(now, ready, repeat_ms)) {
                return;
            }
            const bool needs_target = skill_idx != 103 && skill_idx != 106 && skill_idx != 109 &&
                                      skill_idx != 110 && skill_idx != 112;
            MonsterEntity* target = needs_target ? world.find_monster(target_id) : nullptr;
            if (needs_target) {
                const int range = skill_cast_range(*def, 1, 208) + kPveRangeTolerance;
                if (!target || target->hp <= 0 || target->map != c.map ||
                    protocol::MonsterRaceInfo::is_openable(target->race) ||
                    !combat::in_attack_range(c.px, c.py, target->x, target->y, range)) {
                    return;
                }
            }
            int destination_z = c.pz;
            if (skill_idx == 108 && indoor_geometry != nullptr) {
                float height = 0;
                if (!terrain::IndoorCollision::resolve_standing(*indoor_geometry,
                                                                {static_cast<float>(target->x),
                                                                 coords::to_client_y(c.pz),
                                                                 static_cast<float>(target->y)},
                                                                height)) {
                    return;
                }
                destination_z = coords::to_server_z(height);
            }
            const int cost = std::max(0, def->rage);
            if (c.rage < cost) {
                if (c.sock) {
                    c.sock->enqueue(frame_message(static_cast<std::uint8_t>(MsgId::NotEnoughRage)));
                }
                return;
            }
            add_rage(c, -cost);
            ready = std::max(now, ready) + repeat_ms;

            auto apply_self_buff = [&](SkillBuffId id, int duration_sec, int v1, int v2) {
                std::int32_t remain = 0;
                std::uint64_t bstate = 0;
                if (c.skill_buffs.apply(id,
                                        protocol::animal_skill_class(race),
                                        skill_idx,
                                        duration_sec,
                                        v1,
                                        v2,
                                        unix_now_sec(),
                                        remain,
                                        bstate)) {
                    sync_skill_buffs_to_client(c);
                    recompute_combat(c, world);
                }
            };

            switch (skill_idx) {
            case 103:
                apply_self_buff(SkillBuffId::ArcherEscape, 15, 100, 0);
                break;
            case 106:
                apply_self_buff(SkillBuffId::YungsangRage, 15, 0, 0);
                break;
            case 109:
                apply_self_buff(SkillBuffId::BlessCritical, 15, 100, 0);
                break;
            case 110:
                apply_self_buff(SkillBuffId::ThiefHiding, 20, 1, 0);
                world.clear_aggro_on_player(c.player_id);
                break;
            default:
                break;
            }

            const int str = c.str + c.prefix_bonus.str;
            const int intl = c.intl + c.prefix_bonus.intl;
            const int dex = c.dex + c.prefix_bonus.dex;
            int damage = 0;
            switch (skill_idx) {
            case 101:
                damage = c.max_magic + c.max_magic / 5 + 2 * intl;
                break;
            case 102:
                damage = intl + c.max_magic / 2;
                break;
            case 104:
                damage = c.max_attack + c.max_attack / 5 + 2 * str;
                break;
            case 105:
                damage = c.max_attack + 2 * c.level;
                break;
            case 107:
                damage = c.max_attack + c.max_attack / 5 + 2 * dex;
                break;
            case 108:
            case 111:
                damage = c.max_attack;
                break;
            case 112:
                damage = c.max_magic;
                break;
            default:
                break;
            }
            if (skill_idx == 111) {
                damage *= 3;
            }
            if (skill_idx == 108) {
                c.px = target->x;
                c.py = target->y;
                c.pz = destination_z;
                c.movement_budget = {};
                const auto snap = frame_move_before(c.player_id, c.px, c.py, c.pz, 0);
                broadcast_transform_action(clients, snap);
                std::int32_t remain = 0;
                std::uint64_t bstate = 0;
                (void) target->skill_buffs.apply(SkillBuffId::ArcherVanishConfidence,
                                                 protocol::animal_skill_class(race),
                                                 skill_idx,
                                                 10,
                                                 -50,
                                                 0,
                                                 unix_now_sec(),
                                                 remain,
                                                 bstate);
            }

            const auto packet = protocol::Skill::frame_server(
                skill_idx, c.player_id, target_id == 0 ? c.player_id : target_id, 1);
            broadcast_transform_action(clients, packet);

            auto strike_monster = [&](MonsterEntity* monster, int dealt, bool slow, bool stun) {
                if (!monster || monster->hp <= 0 || monster->map != c.map || dealt <= 0) {
                    return;
                }
                (void) world.apply_player_attack(c.player_id, monster->id, dealt, c.px, c.py);
                if (slow) {
                    (void) world.apply_monster_slow(monster->id, 8.0f, -50);
                }
                if (stun) {
                    std::int32_t remain = 0;
                    std::uint64_t bstate = 0;
                    (void) monster->skill_buffs.apply(SkillBuffId::ArcherStun,
                                                      protocol::animal_skill_class(race),
                                                      skill_idx,
                                                      5,
                                                      1,
                                                      0,
                                                      unix_now_sec(),
                                                      remain,
                                                      bstate);
                }
                if (monster->hp <= 0) {
                    const int def_index = monster->def_index;
                    const int dead_x = monster->x;
                    const int dead_y = monster->y;
                    const bool maguni = (monster->gstate & protocol::kCgsKnee) != 0;
                    begin_combat_corpse(*monster);
                    const auto action = maguni ? protocol::Skill::frame_action_knee(monster->id)
                                               : protocol::Skill::frame_action_die(monster->id);
                    broadcast_known_monster(clients, monster->id, action);
                    reward_monster_death(
                        world, next_iid, clients, monster->id, def_index, dead_x, dead_y, store);
                }
            };

            if (skill_idx == 112) {
                constexpr int kShinRhoeRadius = 192;
                for (auto& monster : world.monsters()) {
                    if (monster.hp <= 0 || monster.map != c.map) {
                        continue;
                    }
                    if (!combat::in_attack_range(
                            c.px, c.py, monster.x, monster.y, kShinRhoeRadius)) {
                        continue;
                    }
                    strike_monster(&monster, damage, false, false);
                }
                return;
            }
            if (damage <= 0 || target_id == 0) {
                return;
            }
            strike_monster(target, damage, skill_idx == 102, skill_idx == 105);
        }

        /** Expires registered pets and rides before dead-player handling. */
        void tick_pet_and_ride_expiry(ClientSession& c,
                                      std::vector<ClientSession>& clients,
                                      const GameWorld& world,
                                      IDataStore* store,
                                      std::int64_t now_unix) {
            bool expired_pet = false;
            for (auto& slot : c.bag) {
                if (!slot.equipped || slot.count <= 0 || slot.pet_expire_at <= 0 ||
                    slot.pet_expire_at > now_unix ||
                    world.pet_defs().find(slot.index) == world.pet_defs().end()) {
                    continue;
                }
                const std::uint32_t iid = slot.iid;
                const int index = slot.index;
                const int prefix = slot.prefix;
                if (store && c.character_id > 0) {
                    (void) store->delete_item(static_cast<std::int32_t>(iid));
                }
                slot = {};
                expired_pet = true;
                if (c.sock) {
                    c.sock->enqueue(protocol::ItemWear::frame_server_put_off(
                        c.player_id, iid, static_cast<std::uint16_t>(index)));
                    c.sock->enqueue(
                        frame_insert_item(iid,
                                          static_cast<std::uint16_t>(index),
                                          static_cast<std::uint8_t>(std::clamp(prefix, 0, 255)),
                                          protocol::pack_insert_info(true, 0, 0),
                                          0));
                }
            }
            if (expired_pet) {
                c.next_pet_heal_ms = 0;
                refresh_visual_wear(c, world);
                recompute_combat(c, world);
            }
            bool expired_ride = false;
            for (auto& slot : c.bag) {
                if (!slot.equipped || slot.count <= 0 || slot.ride_expire_at <= 0 ||
                    slot.ride_expire_at > now_unix ||
                    world.riding_defs().find(slot.index) == world.riding_defs().end()) {
                    continue;
                }
                if (c.mounted) {
                    (void) set_riding(c, false, clients, world);
                }
                const std::uint32_t iid = slot.iid;
                const int index = slot.index;
                const int prefix = slot.prefix;
                if (store && c.character_id > 0) {
                    (void) store->delete_item(static_cast<std::int32_t>(iid));
                }
                slot = {};
                expired_ride = true;
                if (c.sock) {
                    c.sock->enqueue(protocol::ItemWear::frame_server_put_off(
                        c.player_id, iid, static_cast<std::uint16_t>(index)));
                    c.sock->enqueue(
                        frame_insert_item(iid,
                                          static_cast<std::uint16_t>(index),
                                          static_cast<std::uint8_t>(std::clamp(prefix, 0, 255)),
                                          protocol::pack_insert_info(true, 0, 0),
                                          0));
                }
            }
            if (expired_ride) {
                broadcast_riding_state(c, clients, world);
            }
        }

        /** Applies resource pulses in their compatibility order. */
        void tick_resource_regeneration(ClientSession& c,
                                        std::vector<ClientSession>& clients,
                                        const GameWorld& world,
                                        std::uint64_t now_ms) {
            using player_regen::add_clamped;
            using player_regen::kStandHpIntervalMs;
            using player_regen::kStandMpIntervalMs;
            using player_regen::sit_hp_amount;
            using player_regen::sit_mp_amount;
            using player_regen::sit_next_due_ms;
            using player_regen::sit_random_hi;
            using player_regen::standing_hp_amount;
            using player_regen::standing_mp_amount;

            const auto talents = protocol::talent_bonuses(c.talent_mask);
            if (c.next_talent_regen_ms == 0) {
                c.next_talent_regen_ms = now_ms + 2000;
            }
            if (now_ms >= c.next_talent_regen_ms) {
                c.next_talent_regen_ms = now_ms + 2000;
                if (add_clamped(c.cur_hp, c.max_hp, talents.hp_per_pulse)) {
                    send_cur_property(c, protocol::PropertyType::CurHp, c.cur_hp);
                }
                if (add_clamped(c.cur_mp, c.max_mp, talents.mp_per_pulse)) {
                    send_cur_property(c, protocol::PropertyType::CurMp, c.cur_mp);
                }
            }
            int pet_heal = 0;
            for (const auto& slot : c.bag) {
                if (!slot.equipped || slot.count <= 0) {
                    continue;
                }
                const auto it = world.pet_defs().find(slot.index);
                if (it != world.pet_defs().end()) {
                    pet_heal = std::max(pet_heal, it->second.heal_per_two_seconds);
                }
            }
            if (pet_heal <= 0) {
                c.next_pet_heal_ms = 0;
            } else if (c.next_pet_heal_ms == 0) {
                c.next_pet_heal_ms = now_ms + 2000;
            } else if (now_ms >= c.next_pet_heal_ms) {
                if (add_clamped(c.cur_hp, c.max_hp, pet_heal)) {
                    send_cur_property(c, protocol::PropertyType::CurHp, c.cur_hp);
                }
                c.next_pet_heal_ms = now_ms + 2000;
            }
            if (c.cur_hp < c.max_hp && now_ms >= c.next_stand_hp_ms) {
                if (add_clamped(c.cur_hp, c.max_hp, standing_hp_amount(c.max_hp))) {
                    send_cur_property(c, protocol::PropertyType::CurHp, c.cur_hp);
                }
                c.next_stand_hp_ms = now_ms + static_cast<std::uint64_t>(kStandHpIntervalMs);
            }
            if (c.cur_mp < c.max_mp && now_ms >= c.next_stand_mp_ms) {
                if (add_clamped(c.cur_mp, c.max_mp, standing_mp_amount(c.max_mp))) {
                    send_cur_property(c, protocol::PropertyType::CurMp, c.cur_mp);
                }
                c.next_stand_mp_ms = now_ms + static_cast<std::uint64_t>(kStandMpIntervalMs);
            }
            const int meditation_level = c.skill_buffs.meditation_level();
            if (meditation_level <= 0) {
                c.next_meditation_ms = 0;
            } else if (c.next_meditation_ms == 0) {
                c.next_meditation_ms = now_ms + 4000;
            } else if (now_ms >= c.next_meditation_ms) {
                if (c.cur_mp < c.max_mp) {
                    const int wisdom_bonus = meditation_level * (c.wis + c.prefix_bonus.wis) / 15;
                    const int random_bonus = combat::irand(0, meditation_level + 1);
                    const int amount =
                        std::min(wisdom_bonus + random_bonus, 5 * meditation_level + 5);
                    if (add_clamped(c.cur_mp, c.max_mp, amount)) {
                        send_cur_property(c, protocol::PropertyType::CurMp, c.cur_mp);
                    }
                }
                c.next_meditation_ms = now_ms + 4000;
            }
            const int recovery = c.skill_buffs.recovery_chant_points();
            if (recovery <= 0) {
                c.next_knight_recovery_ms = 0;
            } else if (c.next_knight_recovery_ms == 0) {
                c.next_knight_recovery_ms = now_ms + 3000;
            } else if (now_ms >= c.next_knight_recovery_ms) {
                if (c.cur_hp < c.max_hp && add_clamped(c.cur_hp, c.max_hp, recovery)) {
                    send_cur_property(c, protocol::PropertyType::CurHp, c.cur_hp);
                }
                c.next_knight_recovery_ms = now_ms + 3000;
            }
            if (c.resting && now_ms >= c.next_sit_regen_ms) {
                const int hi = sit_random_hi(c.rest_point);
                const int hp_roll = combat::irand(0, hi);
                const int mp_roll = combat::irand(0, hi);
                if (c.cur_hp < c.max_hp &&
                    add_clamped(c.cur_hp, c.max_hp, sit_hp_amount(c.rest_point, hp_roll))) {
                    send_cur_property(c, protocol::PropertyType::CurHp, c.cur_hp);
                }
                if (c.cur_mp < c.max_mp &&
                    add_clamped(c.cur_mp, c.max_mp, sit_mp_amount(c.rest_point, mp_roll))) {
                    send_cur_property(c, protocol::PropertyType::CurMp, c.cur_mp);
                }
                c.next_sit_regen_ms = sit_next_due_ms(now_ms);
            }
            if (c.rest_food.active()) {
                const RestFoodPulse pulse = c.rest_food.tick(now_ms);
                if (pulse.hp_add > 0 && add_clamped(c.cur_hp, c.max_hp, pulse.hp_add)) {
                    send_cur_property(c, protocol::PropertyType::CurHp, c.cur_hp);
                }
                if (pulse.mp_add > 0 && add_clamped(c.cur_mp, c.max_mp, pulse.mp_add)) {
                    send_cur_property(c, protocol::PropertyType::CurMp, c.cur_mp);
                }
                if (pulse.hp_expired || pulse.mp_expired) {
                    broadcast_mstate(c, clients);
                }
            }
        }

        /** Advances worn-animal EXP before draining active-form rage. */
        void tick_transform_progress_and_rage(ClientSession& c,
                                              std::vector<ClientSession>& clients,
                                              const GameWorld& world,
                                              IDataStore* store,
                                              std::uint64_t now_ms) {
            using player_regen::kTransformTickMs;
            using player_regen::tick_transform_exp;

            if (c.transform.index > 0 && now_ms >= c.next_transform_tick_ms) {
                c.next_transform_tick_ms = now_ms + static_cast<std::uint64_t>(kTransformTickMs);
                const player_regen::TransformExpTickResult result =
                    tick_transform_exp(c.transform, c.level);
                if (result.applied) {
                    sync_transform_progress_to_equipped_item(c);
                    if (c.sock) {
                        send_transform_item_info(c, result.added);
                    }
                    if (result.leveled) {
                        flush_worn_transform_item(store, c);
                        recompute_combat(c, world);
                        send_progression_snapshot(c);
                    }
                }
            }
            if ((c.gstate & protocol::kCgsOnTransform) != 0) {
                if (c.next_dec_rage_ms == 0) {
                    c.next_dec_rage_ms = now_ms + 5000;
                } else if (now_ms >= c.next_dec_rage_ms) {
                    const int stage = std::clamp(c.transform_stage, 1, 3);
                    add_rage(c, -protocol::dec_rage_for_stage(stage));
                    if (c.rage <= 0) {
                        free_transform_form(c, clients, world);
                    } else {
                        c.next_dec_rage_ms = now_ms + 5000;
                    }
                }
            }
        }

        /** Standing + sit regen, sit-food pulses, and the 1s transform wear tick (compatibility
         * behavior).
         */
        void tick_player_regen_and_transform(ClientSession& c,
                                             std::vector<ClientSession>& clients,
                                             const GameWorld& world,
                                             IDataStore* store,
                                             std::uint64_t now_ms,
                                             std::int64_t (*unix_seconds)() = unix_now_sec) {
            if (c.phase != SessionPhase::Playing) {
                return;
            }
            const std::int64_t now_unix = unix_seconds();
            tick_pet_and_ride_expiry(c, clients, world, store, now_unix);
            if (c.cur_hp <= 0) {
                if (c.mounted) {
                    (void) set_riding(c, false, clients, world);
                }
                return;
            }
            tick_resource_regeneration(c, clients, world, now_ms);
            tick_transform_progress_and_rage(c, clients, world, store, now_ms);
        }

        /** Seeds PU for a configured start level (level-1 → 5). */
        void init_progression_points(ClientSession& c) {
            const int lv = std::max(1, c.level);
            c.exp = 0;
            c.pu_point = protocol::kPuPerLevel * lv;
            c.su_point = protocol::kSuPerLevel * std::max(0, lv - 1);
        }

        /** Sends current EXP / level / PU / SU / HP / MP / combat stats to the owning
         * client. */
        std::int64_t talent_unix_ms() {
            return std::chrono::duration_cast<std::chrono::milliseconds>(
                       std::chrono::system_clock::now().time_since_epoch())
                .count();
        }

        /** Time reads remain lazy and ordered at their previous request conditions. */
        struct TalentRequestClock {
            std::int64_t (*unix_ms)() = talent_unix_ms;
            std::uint64_t (*steady_ms)() = steady_ms_now;
        };

        void send_talent_state(ClientSession& c,
                               protocol::TalentStatus status,
                               const TalentRequestClock& clock) {
            if (!c.sock) {
                return;
            }
            const auto now_ms = clock.steady_ms();
            protocol::TalentState state;
            state.mask = c.talent_mask;
            state.level = c.level;
            state.status = status;
            state.beacon_cooldown_ms = static_cast<std::uint32_t>(std::clamp<std::int64_t>(
                c.beacon_ready_at - clock.unix_ms(), 0, protocol::kBeaconCooldownMs));
            state.beacon_active_ms = static_cast<std::uint32_t>(
                c.beacon_active_until_ms > now_ms ? c.beacon_active_until_ms - now_ms : 0);
            c.sock->enqueue(protocol::frame_talent_state(state));
        }

        void send_talent_state(ClientSession& c, protocol::TalentStatus status) {
            send_talent_state(c, status, TalentRequestClock{});
        }

        void send_progression_snapshot(ClientSession& c, bool include_talents) {
            if (include_talents) {
                send_talent_state(c);
            }
            if (!c.sock) {
                return;
            }
            int move_speed = c.transform_mspeed_percent;
            if (c.mounted && c.collection_world) {
                if (const auto* riding = registered_ride_def(c, *c.collection_world)) {
                    move_speed = riding->movement_speed_percent;
                }
            }
            c.sock->enqueue(protocol::Property::frame_update_mproperty(
                c.player_id,
                protocol::kPropertyMSpeed,
                static_cast<std::int16_t>(
                    std::clamp(move_speed + (static_cast<int>(c.collection_bonus.ability[12]) +
                                             protocol::talent_bonuses(c.talent_mask).speed_percent),
                               -100,
                               300))));
            c.sock->enqueue(protocol::Property::frame_update_level(
                std::clamp(c.level, 1, protocol::kMaxPlayerLevel)));
            c.sock->enqueue(protocol::Property::frame_update_exp(c.exp, 0));
            c.sock->enqueue(protocol::Property::frame_update_points(
                static_cast<std::uint8_t>(protocol::PropertyType::PuPoint),
                combat::clamp_nonneg_i32(c.pu_point)));
            c.sock->enqueue(protocol::Property::frame_update_points(
                static_cast<std::uint8_t>(protocol::PropertyType::SuPoint),
                combat::clamp_nonneg_i32(c.su_point)));
            send_cur_property(c, protocol::PropertyType::Contribute, c.contribution);
            c.sock->enqueue(protocol::Property::frame_update_vital(
                static_cast<std::uint8_t>(protocol::PropertyType::Hp), c.cur_hp, c.max_hp));
            c.sock->enqueue(protocol::Property::frame_update_vital(
                static_cast<std::uint8_t>(protocol::PropertyType::Mp), c.cur_mp, c.max_mp));
            auto send_word = [&](protocol::PropertyType prop, std::int32_t value) {
                c.sock->enqueue(protocol::Property::frame_update(static_cast<std::uint8_t>(prop),
                                                                 combat::clamp_nonneg_i32(value)));
            };
            // The character overview stages allocations against these base values. Prefix
            // bonuses are combat-only and must not affect the GetNeedPoint curve.
            send_word(protocol::PropertyType::Str, c.str);
            send_word(protocol::PropertyType::Hth, c.hth);
            send_word(protocol::PropertyType::Int, c.intl);
            send_word(protocol::PropertyType::Wis, c.wis);
            send_word(protocol::PropertyType::Dex, c.dex);
            send_word(protocol::PropertyType::Hit, c.hit + c.skill_buffs.concentration_hit());
            send_word(protocol::PropertyType::Dodge, c.dodge);
            send_word(protocol::PropertyType::MinAttack, c.min_attack);
            send_word(protocol::PropertyType::MaxAttack, c.max_attack);
            send_word(protocol::PropertyType::MinMagic, c.min_magic);
            send_word(protocol::PropertyType::MaxMagic, c.max_magic);
            send_word(protocol::PropertyType::Defense, c.defense + c.skill_buffs.stone_defense());
            send_word(protocol::PropertyType::Absorb, c.absorb + c.skill_buffs.stone_absorb());
            send_word(protocol::PropertyType::ResFire, c.res_fire);
            send_word(protocol::PropertyType::ResIce, c.res_ice);
            send_word(protocol::PropertyType::ResLitning, c.res_lightning);
            send_word(protocol::PropertyType::ResCurse, c.res_curse);
            send_word(protocol::PropertyType::ResPalsy, c.res_palsy);
            c.sock->enqueue(protocol::Property::frame_update(protocol::kPropertyRage, c.rage));
            c.sock->enqueue(protocol::Property::frame_update(protocol::kPropertyMortal, c.mortal));
            send_transform_item_info(c);
        }

        /**
         * Replaces the player specialty mask, persists, syncs, and auto-learns skills.
         * @param c Session to update.
         * @param store Character store (may be null).
         * @param world World (skill defs for auto-learn).
         * @param specialty New specialty bitmask.
         */
        void apply_specialty_mask(ClientSession& c,
                                  IDataStore* store,
                                  const GameWorld& world,
                                  int specialty) {
            c.specialty = std::max(1, specialty);
            persist_character(store, c);
            send_specialty_up(c);
            const auto changes = apply_auto_learn(
                c.learned_skills, world.skill_defs(), c.clazz, c.level, c.specialty);
            persist_skill_changes(store, c.character_id, changes);
            if (c.sock) {
                for (const SkillRankChange& change : changes) {
                    c.sock->enqueue(protocol::Skill::frame_skill_up(
                        static_cast<std::uint8_t>(std::clamp(change.index, 0, 255)),
                        static_cast<std::uint8_t>(std::clamp(change.level, 0, 255))));
                }
            }
            sync_rest_point(c);
            recompute_combat(c, world);
            send_progression_snapshot(c);
        }

        /**
         * Maps /job tier (+ optional a/b path) to a specialty bitmask.
         * @param tier 0=wander, 1=1st, 2=2nd, 3=3rd.
         * @param path 0=auto from current, 'a' or 'b' forced branch.
         * @param current Current specialty (for auto path on tier 2/3).
         * @return Specialty mask, or -1 when invalid.
         */
        [[nodiscard]] int specialty_for_job_tier(int tier, char path, int current) {
            using protocol::kSpecialtyFirstJob;
            using protocol::kSpecialtySecondJobA;
            using protocol::kSpecialtySecondJobB;
            using protocol::kSpecialtyThirdJobA;
            using protocol::kSpecialtyThirdJobB;
            using protocol::kStartingSpecialty;
            using protocol::specialty_meets_grade;
            const auto cur = static_cast<std::uint32_t>(std::max(1, current));
            const bool prefer_b =
                path == 'b' || (path == 0 && (specialty_meets_grade(cur, kSpecialtySecondJobB) ||
                                              specialty_meets_grade(cur, kSpecialtyThirdJobB)));
            switch (tier) {
            case 0:
                return static_cast<int>(kStartingSpecialty);
            case 1:
                return static_cast<int>(kSpecialtyFirstJob);
            case 2:
                return static_cast<int>(prefer_b ? kSpecialtySecondJobB : kSpecialtySecondJobA);
            case 3:
                return static_cast<int>(prefer_b ? kSpecialtyThirdJobB : kSpecialtyThirdJobA);
            default:
                return -1;
            }
        }

        /** Usage string for the /job chat command. */
        constexpr const char* kJobCommandUsage =
            "Usage: /job [0|1|2|3] [a|b]  (0=wander, 1=1st, 2/3=2nd/3rd; a|b = path)";

        /** Returns a mutable primary pointer for property 0..4, or nullptr. */
        [[nodiscard]] std::int32_t* primary_stat_ptr(ClientSession& c, std::uint8_t property) {
            switch (static_cast<protocol::PropertyType>(property)) {
            case protocol::PropertyType::Str:
                return &c.str;
            case protocol::PropertyType::Hth:
                return &c.hth;
            case protocol::PropertyType::Int:
                return &c.intl;
            case protocol::PropertyType::Wis:
                return &c.wis;
            case protocol::PropertyType::Dex:
                return &c.dex;
            default:
                return nullptr;
            }
        }

        /**
         * Applies one level-up (LevelUp): +1 level, +5 PU, auto-learn, full heal,
         * Effect.
         * @param clients All sessions (broadcast Effect in sight).
         * @param world World for sight checks.
         */
        void apply_level_up(ClientSession& c,
                            std::vector<ClientSession>& clients,
                            const GameWorld& world,
                            IDataStore* store,
                            const LevelMailRewardCatalog* level_mail_rewards = nullptr) {
            c.level = std::min(c.level + 1, protocol::kMaxPlayerLevel);
            send_talent_state(c);
            if (store && c.character_id > 0) {
                const auto now = std::chrono::duration_cast<std::chrono::seconds>(
                                     std::chrono::system_clock::now().time_since_epoch())
                                     .count();
                const LevelMailRewardCatalog* catalog =
                    level_mail_rewards ? level_mail_rewards : g_level_mail_rewards;
                const std::vector<LevelMailReward> rewards =
                    catalog ? catalog->rewards_for_level(c.level) : std::vector<LevelMailReward>{};
                bool inbox_updated = false;
                for (const LevelMailReward& reward : rewards) {
                    SystemMailRecord mail;
                    mail.character_id = c.character_id;
                    mail.source_key = "level-reward:" + std::to_string(c.level);
                    mail.subject = "Level Up Reward";
                    mail.body =
                        "Congratulations on reaching level " + std::to_string(c.level) + ".";
                    mail.item_index = reward.item_id;
                    mail.item_count = reward.count;
                    mail.created_at = now;
                    inbox_updated = store->ensure_system_mail(mail) || inbox_updated;
                }
                if (inbox_updated) {
                    send_system_mail_list(store, c);
                }
            }
            c.pu_point += protocol::kPuPerLevel;
            c.su_point += protocol::kSuPerLevel;
            const auto changes = apply_auto_learn(
                c.learned_skills, world.skill_defs(), c.clazz, c.level, c.specialty);
            sync_rest_point(c);
            persist_skill_changes(store, c.character_id, changes);
            recompute_combat(c, world);
            // LevelUp sets current vitals to the revised maxima.
            c.cur_hp = c.max_hp;
            c.cur_mp = c.max_mp;
            if (c.sock) {
                c.sock->enqueue(protocol::Property::frame_update_level(c.level));
                c.sock->enqueue(protocol::Property::frame_update_points(
                    static_cast<std::uint8_t>(protocol::PropertyType::PuPoint),
                    combat::clamp_nonneg_i32(c.pu_point)));
                c.sock->enqueue(protocol::Property::frame_update_points(
                    static_cast<std::uint8_t>(protocol::PropertyType::SuPoint),
                    combat::clamp_nonneg_i32(c.su_point)));
                c.sock->enqueue(protocol::Property::frame_update_vital(
                    static_cast<std::uint8_t>(protocol::PropertyType::Hp), c.cur_hp, c.max_hp));
                c.sock->enqueue(protocol::Property::frame_update_vital(
                    static_cast<std::uint8_t>(protocol::PropertyType::Mp), c.cur_mp, c.max_mp));
                for (const SkillRankChange& change : changes) {
                    c.sock->enqueue(protocol::Skill::frame_skill_up(
                        static_cast<std::uint8_t>(std::clamp(change.index, 0, 255)),
                        static_cast<std::uint8_t>(std::clamp(change.level, 0, 255))));
                }
            }
            if (g_guilds && !g_guilds->level_up(character_from_session(c), unix_now_sec())) {
                log::error("Guild level-up award could not be persisted");
            }
            persist_character(store, c);
            const auto fx = protocol::Effect::frame(
                c.player_id, static_cast<std::uint8_t>(protocol::EffectType::LevelUp));
            for (auto& peer : clients) {
                if (peer.phase == SessionPhase::Playing && peer.sock &&
                    same_map_in_sight(peer.map, peer.px, peer.py, c.map, c.px, c.py)) {
                    peer.sock->enqueue(fx);
                }
            }
        }

        /**
         * Spends overflow EXP into levels (UpdateProperty P_EXP add loop).
         * @param c Session to update.
         * @param clients All sessions (level-up FX).
         * @param world Combat tables.
         * @param store Persistence.
         */
        void consume_player_exp(ClientSession& c,
                                std::vector<ClientSession>& clients,
                                const GameWorld& world,
                                IDataStore* store,
                                const LevelMailRewardCatalog* level_mail_rewards = nullptr) {
            while (c.level < protocol::kMaxPlayerLevel &&
                   c.exp >= protocol::need_exp_for_level(c.level)) {
                c.exp -= protocol::need_exp_for_level(c.level);
                apply_level_up(c, clients, world, store, level_mail_rewards);
            }
        }

        /**
         * Awards EXP and runs the level-up loop (UpdateProperty P_EXP add).
         * @param amount Positive EXP to add.
         */
        void add_exp(ClientSession& c,
                     std::int64_t amount,
                     std::vector<ClientSession>& clients,
                     const GameWorld& world,
                     IDataStore* store,
                     const LevelMailRewardCatalog* level_mail_rewards = nullptr) {
            if (amount <= 0 || c.cur_hp <= 0) {
                return;
            }
            if (g_exp_event != nullptr) {
                const std::int32_t percent = g_exp_event->active_bonus_percent(unix_now_sec());
                if (percent > 0) {
                    amount += amount / 100 * percent + amount % 100 * percent / 100;
                }
            }
            c.exp += amount;
            consume_player_exp(c, clients, world, store, level_mail_rewards);
            if (c.sock) {
                c.sock->enqueue(protocol::Property::frame_update_exp(c.exp, amount));
            }
        }

        /**
         * Subtracts EXP on revival (CutdownExp).
         * @param extra_cut Percent of cut to forgive (0 = full cut; 100 = skip).
         */
        void cutdown_exp(ClientSession& c, int extra_cut, int pvp_percent = 0) {
            if (extra_cut >= 100) {
                return;
            }
            std::int64_t cut = pvp_percent == 0
                                   ? protocol::cutdown_exp_amount(c.level)
                                   : protocol::need_exp_for_level(c.level) * pvp_percent / 100;
            if (cut <= 0) {
                return;
            }
            if (extra_cut > 0) {
                cut -= cut * extra_cut / 100;
            }
            if (cut <= 0) {
                return;
            }
            if (c.exp < cut) {
                cut = c.exp;
            }
            c.exp -= cut;
            if (c.sock) {
                c.sock->enqueue(protocol::Property::frame_update_exp(c.exp, -cut));
            }
        }

        bool party_share_eligible(const ClientSession& player, int map, int x, int y) {
            const auto dx = static_cast<std::int64_t>(player.px) - x;
            const auto dy = static_cast<std::int64_t>(player.py) - y;
            return player.phase == SessionPhase::Playing && player.sock && player.sock->alive() &&
                   player.cur_hp > 0 && !player.tele_pending && player.map == map &&
                   dx * dx + dy * dy <= static_cast<std::int64_t>(protocol::kPartyShareRadius) *
                                            protocol::kPartyShareRadius;
        }

        /** Distributes kill EXP by accumulated hostility and selects the drop owner. */
        MonsterRewardResult
        allot_monster_kill_exp(const MonsterEntity* monster,
                               const MonsterDef* def,
                               std::vector<ClientSession>& clients,
                               const GameWorld& world,
                               IDataStore* store,
                               const LevelMailRewardCatalog* level_mail_rewards) {
            MonsterRewardResult result;
            if (!monster || !def || monster->hostility_by_player.empty()) {
                return result;
            }
            const MonsterRewardCoverage coverage =
                calculate_monster_reward_coverage(*monster, def->exp);
            if (coverage.credited_damage <= 0) {
                return result;
            }
            result.loot_access = coverage.loot_access;

            std::int64_t total_hostility = 0;
            std::unordered_map<std::uint64_t, std::int64_t> group_hostility;
            for (const auto& entry : monster->hostility_by_player) {
                if (entry.second <= 0) {
                    continue;
                }
                total_hostility += entry.second;
                ClientSession* player = nullptr;
                for (auto& candidate : clients) {
                    if (candidate.phase == SessionPhase::Playing &&
                        candidate.player_id == entry.first) {
                        player = &candidate;
                        break;
                    }
                }
                if (!player) {
                    continue;
                }
                const std::uint64_t group_key = player->party_id != 0
                                                    ? static_cast<std::uint64_t>(player->party_id)
                                                    : (std::uint64_t{1} << 32) | player->player_id;
                group_hostility[group_key] += entry.second;
            }
            if (total_hostility <= 0 || group_hostility.empty()) {
                return result;
            }

            std::uint64_t best_group = 0;
            std::int64_t best_group_hostility = 0;
            for (const auto& entry : group_hostility) {
                if (entry.second > best_group_hostility ||
                    (entry.second == best_group_hostility && entry.first < best_group)) {
                    best_group = entry.first;
                    best_group_hostility = entry.second;
                }
            }
            if (best_group < (std::uint64_t{1} << 32)) {
                result.owner_party_id = static_cast<std::uint32_t>(best_group);
            }

            std::unordered_map<std::uint32_t, std::int64_t> experience;
            std::int64_t best_owner_hostility = 0;
            for (const auto& entry : monster->hostility_by_player) {
                if (entry.second <= 0) {
                    continue;
                }
                ClientSession* player = nullptr;
                for (auto& candidate : clients) {
                    if (candidate.phase == SessionPhase::Playing &&
                        candidate.player_id == entry.first) {
                        player = &candidate;
                        break;
                    }
                }
                if (!player) {
                    continue;
                }

                const std::uint64_t group_key = player->party_id != 0
                                                    ? static_cast<std::uint64_t>(player->party_id)
                                                    : (std::uint64_t{1} << 32) | player->player_id;
                if (group_key == best_group &&
                    (entry.second > best_owner_hostility ||
                     (entry.second == best_owner_hostility &&
                      (!result.drop_owner || player->player_id < result.drop_owner->player_id)))) {
                    result.drop_owner = player;
                    best_owner_hostility = entry.second;
                }

                const auto share = static_cast<std::int64_t>(
                    static_cast<long double>(coverage.exp_pool) * entry.second / total_hostility);
                std::vector<ClientSession*> recipients;
                if (player->party_id != 0) {
                    for (auto& peer : clients) {
                        if (peer.party_id == player->party_id &&
                            party_share_eligible(peer, monster->map, monster->x, monster->y)) {
                            recipients.push_back(&peer);
                        }
                    }
                } else {
                    recipients.push_back(player);
                }
                if (recipients.empty()) {
                    continue;
                }
                std::sort(recipients.begin(), recipients.end(), [](const auto* a, const auto* b) {
                    return a->player_id < b->player_id;
                });
                for (std::size_t i = 0; i < recipients.size(); ++i) {
                    experience[recipients[i]->player_id] +=
                        share / static_cast<std::int64_t>(recipients.size()) +
                        (i < static_cast<std::size_t>(share %
                                                      static_cast<std::int64_t>(recipients.size()))
                             ? 1
                             : 0);
                }
            }
            for (auto& recipient : clients) {
                auto* player = &recipient;
                const auto share = experience[player->player_id];
                const std::int64_t revised =
                    protocol::revise_kill_exp(share, player->level, def->level);
                if (revised <= 0) {
                    continue;
                }
                const std::int64_t bonus = player->pay_buffs.has(protocol::kCbsStoneExp)
                                               ? revised / 10 * 3 + revised % 10 * 3 / 10
                                               : 0;
                const auto collection =
                    collection_bonuses(collection_items(*player), !player->collection_pve);
                const auto collection_exp =
                    static_cast<std::int64_t>(revised * collection.ability[20] / 100.0);
                add_exp(*player,
                        revised + bonus + collection_exp,
                        clients,
                        world,
                        store,
                        level_mail_rewards);
                if (player->transform.index > 0 &&
                    combat::color_level(def->level, player->level) >= protocol::kColorYellow) {
                    const int base_added = protocol::kill_transform_exp_add(player->level);
                    const int added =
                        base_added + static_cast<int>(base_added * collection.ability[21] / 100.0);
                    const player_regen::TransformExpTickResult transform_result =
                        player_regen::add_transform_exp(player->transform, player->level, added);
                    if (transform_result.applied) {
                        sync_transform_progress_to_equipped_item(*player);
                        if (player->sock) {
                            send_transform_item_info(*player, transform_result.added);
                        }
                        if (transform_result.leveled) {
                            flush_worn_transform_item(store, *player);
                            recompute_combat(*player, world);
                            send_progression_snapshot(*player);
                        }
                    }
                }
            }
            return result;
        }

        // compatibility behavior / MovePlayer: CreateMonster / RemoveMonster by
        // 25-tile sight.
        void sync_monster_interest(ClientSession& c,
                                   const GameWorld& world,
                                   const WorldInterestIndex* index = nullptr) {
            if (!c.sock || c.phase != SessionPhase::Playing || c.player_id == 0) {
                return;
            }
            auto& should_see = c.interest_scratch;
            should_see.clear();
            const auto visit = [&](const MonsterEntity& m) {
                // Keep kneeling Maguni and dying corpses in sight (CreateMonster gstate).
                const bool corpse_visible =
                    m.hp <= 0 && ((m.gstate & protocol::kCgsKnee) != 0 || m.knee_left > 0.0f ||
                                  m.die_remove_left > 0.0f);
                if (m.hp <= 0 && !corpse_visible) {
                    return;
                }
                if (m.map != c.map || !coords::in_sight(c.px, c.py, m.x, m.y)) {
                    return;
                }
                should_see.push_back(m.id);
                if (c.known_monsters.find(m.id) == c.known_monsters.end()) {
                    c.sock->enqueue(frame_create_monster(m));
                    c.known_monsters.insert(m.id);
                }
            };
            if (index) {
                for (const auto* monster : index->monsters(c.map)) {
                    visit(*monster);
                }
            } else {
                for (const auto& monster : world.monsters()) {
                    visit(monster);
                }
            }
            std::sort(should_see.begin(), should_see.end());
            should_see.erase(std::unique(should_see.begin(), should_see.end()), should_see.end());
            // Every visible ID was inserted above; equal counts leave no stale IDs.
            if (c.known_monsters.size() == should_see.size()) {
                return;
            }
            for (auto it = c.known_monsters.begin(); it != c.known_monsters.end();) {
                if (!std::binary_search(should_see.begin(), should_see.end(), *it)) {
                    c.sock->enqueue(frame_remove_monster(*it));
                    it = c.known_monsters.erase(it);
                } else {
                    ++it;
                }
            }
        }

