        /** compatibility behavior sight interest for NPCs (CreateNpc / RemoveNpc). */
        void sync_npc_interest(ClientSession& c,
                               const NpcRegistry& npcs,
                               const WorldInterestIndex* index = nullptr) {
            if (!c.sock || c.phase != SessionPhase::Playing || c.player_id == 0) {
                return;
            }
            auto& should_see = c.interest_scratch;
            should_see.clear();
            const auto visit = [&](const NpcEntity& n) {
                if (n.map != c.map || !coords::in_sight(c.px, c.py, n.x, n.y)) {
                    return;
                }
                should_see.push_back(n.id);
                if (c.known_npcs.find(n.id) == c.known_npcs.end()) {
                    c.sock->enqueue(
                        protocol::Quest::frame_create_npc(NpcRegistry::to_create_info(n)));
                    c.known_npcs.insert(n.id);
                }
            };
            if (index) {
                for (const auto* npc : index->npcs(c.map)) {
                    visit(*npc);
                }
            } else {
                for (const auto& npc : npcs.npcs()) {
                    visit(npc);
                }
            }
            std::sort(should_see.begin(), should_see.end());
            should_see.erase(std::unique(should_see.begin(), should_see.end()), should_see.end());
            if (c.known_npcs.size() == should_see.size()) {
                return;
            }
            for (auto it = c.known_npcs.begin(); it != c.known_npcs.end();) {
                if (!std::binary_search(should_see.begin(), should_see.end(), *it)) {
                    c.sock->enqueue(protocol::Quest::frame_remove_npc(*it));
                    it = c.known_npcs.erase(it);
                } else {
                    ++it;
                }
            }
        }

        const SkillDef* find_skill_def(const GameWorld& world, int clazz, int index) {
            for (const auto& s : world.skill_defs()) {
                if (s.clazz == clazz && s.index == index) {
                    return &s;
                }
            }
            return nullptr;
        }

        [[nodiscard]] int
        skill_cast_range(const SkillDef& def, int skill_level, int fallback_range) {
            if (def.cast_range_by_level.empty()) {
                return fallback_range;
            }
            const int level = std::max(1, skill_level);
            const std::size_t rank = std::min<std::size_t>(static_cast<std::size_t>(level - 1),
                                                           def.cast_range_by_level.size() - 1);
            return std::max(0, def.cast_range_by_level[rank]);
        }

        /** Sends S2C_SKILLINFO for the session's learned combat skills. */
        void send_skill_info(ClientSession& c) {
            if (!c.sock) {
                return;
            }
            std::vector<protocol::SkillRankEntry> entries;
            entries.reserve(c.learned_skills.size());
            for (const auto& [index, level] : c.learned_skills) {
                if (index == protocol::kBeaconSkill) {
                    continue;
                }
                protocol::SkillRankEntry entry;
                entry.index = static_cast<std::uint8_t>(std::clamp(index, 0, 255));
                entry.level = static_cast<std::uint8_t>(std::clamp(level, 0, 255));
                entries.push_back(entry);
            }
            const auto ranks = protocol::talent_ranks(c.talent_mask);
            for (int i = 0; i < 5; ++i) {
                if (ranks[i] > 0) {
                    entries.push_back({static_cast<std::uint8_t>(protocol::kTalentSkillFirst + i),
                                       static_cast<std::uint8_t>(ranks[i])});
                }
            }
            if (protocol::talent_bonuses(c.talent_mask).beacon) {
                entries.push_back({static_cast<std::uint8_t>(protocol::kBeaconSkill), 1});
            }
            c.sock->enqueue(protocol::Skill::frame_skill_info(entries));
        }

        /**
         * Broadcasts the level-up effect to everyone in sight.
         * @param c The player who leveled.
         * @param clients All sessions.
         */
        void broadcast_level_up_fx(const ClientSession& c, std::vector<ClientSession>& clients) {
            const auto fx = protocol::Effect::frame(
                c.player_id, static_cast<std::uint8_t>(protocol::EffectType::LevelUp));
            for (auto& peer : clients) {
                if (peer.phase == SessionPhase::Playing && peer.sock &&
                    same_map_in_sight(peer.map, peer.px, peer.py, c.map, c.px, c.py)) {
                    peer.sock->enqueue(fx);
                }
            }
        }

        /**
         * Sends S2C_SKILLUP for each rank change (level 0 forgets the skill).
         * @param c Session to notify.
         * @param changes Rank changes.
         */
        void send_skill_rank_changes(ClientSession& c,
                                     const std::vector<SkillRankChange>& changes) {
            if (!c.sock) {
                return;
            }
            for (const SkillRankChange& change : changes) {
                c.sock->enqueue(protocol::Skill::frame_skill_up(
                    static_cast<std::uint8_t>(std::clamp(change.index, 0, 255)),
                    static_cast<std::uint8_t>(std::clamp(change.level, 0, 255))));
            }
        }

        /**
         * Sets the character to an absolute level and rebuilds PU, primaries, and
         * auto-learned skills (initial /resetlevel plus skill prune).
         * @param c Session to update.
         * @param clients All sessions (broadcast Effect in sight).
         * @param world World for skill defs and sight.
         * @param store Character store (may be null).
         * @param new_level Target level (clamped to 1..max).
         */
        void apply_level_rebuild(ClientSession& c,
                                 std::vector<ClientSession>& clients,
                                 const GameWorld& world,
                                 IDataStore* store,
                                 int new_level) {
            c.level = std::clamp(new_level, 1, protocol::kMaxPlayerLevel);
            c.exp = 0;
            c.stats_initialized = false;
            c.pu_point = protocol::kPuPerLevel * c.level;
            c.su_point = protocol::kSuPerLevel * std::max(0, c.level - 1);
            if (!protocol::valid_talents(c.talent_mask, c.level)) {
                c.talent_mask = 0;
            }
            const auto changes = sync_learned_skills(
                c.learned_skills, world.skill_defs(), c.clazz, c.level, c.specialty);
            const std::uint64_t cleared = c.skill_buffs.clear();
            if (cleared != 0) {
                send_sub_bstate(c, cleared);
            }
            persist_skill_changes(store, c.character_id, changes);
            sync_rest_point(c);
            recompute_combat(c, world);
            c.cur_hp = c.max_hp;
            c.cur_mp = c.max_mp;
            send_progression_snapshot(c);
            send_skill_rank_changes(c, changes);
            send_skill_info(c);
            persist_character(store, c);
            broadcast_level_up_fx(c, clients);
        }

        /** Sends S2C_SHORTCUT; flag 0 when the character has no saved bar. */
        void send_saved_shortcut(ClientSession& c, IDataStore* store) {
            if (!c.sock) {
                return;
            }
            if (!store || c.character_id <= 0) {
                c.sock->enqueue(protocol::Shortcut::frame_server(nullptr));
                return;
            }
            const std::optional<ShortcutRecord> saved = store->load_shortcuts(c.character_id);
            if (!saved) {
                c.sock->enqueue(protocol::Shortcut::frame_server(nullptr));
                return;
            }
            protocol::ShortcutBar bar;
            bar.active_index = saved->active_index;
            bar.slots = saved->slots;
            c.sock->enqueue(protocol::Shortcut::frame_server(&bar));
        }

        std::uint64_t steady_ms_now() {
            using clock = std::chrono::steady_clock;
            return static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
                                                  clock::now().time_since_epoch())
                                                  .count());
        }

        std::int64_t unix_seconds_now() {
            using clock = std::chrono::system_clock;
            return std::chrono::duration_cast<std::chrono::seconds>(clock::now().time_since_epoch())
                .count();
        }

        bool skill_is_castable(const SkillDef& def) {
            // Index 0 = boost/run (handled separately). Index 11 = rest (C2S_REST).
            if (def.index == 0 || def.index == 11) {
                return false;
            }
            // Behead (index 1) has mp=0 and delay=0; it is an explicit CastKind.
            if (def.index == 1) {
                return true;
            }
            // Meditation: mp 0, delay 0, type once — still a C2S_SKILL self buff.
            if (def.clazz == combat::kPcMage && def.index == 15) {
                return true;
            }
            if (def.once) {
                return true;
            }
            if (def.mp > 0 || def.delay_ms > 0 || def.delay_pre_ms > 0) {
                return true;
            }
            return def.usable && (def.compare_cooldown_ms > 0 || def.compare_cooldown_weapon_speed);
        }

        bool skill_is_self_heal(int clazz, int index) {
            // Mage self heal (skill definition class 1 index 8).
            return clazz == combat::kPcMage && index == 8;
        }

        bool skill_is_self_buff(int clazz, int index) {
            if (!SkillBuffSet::buff_id_for_skill(clazz, index).has_value()) {
                return false;
            }
            if (clazz == combat::kPcKnight) {
                return protocol::knight_target_shape(index) == protocol::KnightTargetShape::Self;
            }
            if (clazz == combat::kPcThief) {
                const auto shape = protocol::thief_target_shape(index);
                return shape == protocol::ThiefTargetShape::Self ||
                       shape == protocol::ThiefTargetShape::Party;
            }
            if (clazz != combat::kPcMage) {
                return true;
            }
            return protocol::mage_target_shape(index) == protocol::MageTargetShape::Self;
        }

        bool skill_is_self_cast(int clazz, int index) {
            if (clazz == combat::kPcArcher) {
                const ArcherRoute route = archer_route(index);
                return route == ArcherRoute::SelfBuff || route == ArcherRoute::EmergencyEscape ||
                       route == ArcherRoute::PoisonCloud || route == ArcherRoute::ArrowRain ||
                       route == ArcherRoute::Commonback;
            }
            return skill_is_self_heal(clazz, index) || skill_is_self_buff(clazz, index);
        }

        /** Returns true when a Knight skill needs an equipped shield. */
        [[nodiscard]] bool knight_skill_requires_shield(int skill_index) {
            return skill_index == 15 || skill_index == 22 || skill_index == 34 ||
                   skill_index == 40 || skill_index == 42;
        }

        /** Tests the authoritative equipped bag instances for a shield. */
        [[nodiscard]] bool has_equipped_shield(const ClientSession& c, const GameWorld& world) {
            for (const auto& slot : c.bag) {
                if (!slot.equipped || slot.count <= 0 || slot.index <= 0) {
                    continue;
                }
                const ItemCombatDef* item = item_def_of(world, slot.index);
                if (item && wear_kind_of(*item) == WearKind::Shield) {
                    return true;
                }
            }
            return false;
        }

        /** Maguni kneel duration (compatibility behavior runtime state +10000). */
        constexpr float kMaguniKneeSec = 10.0f;

        /** NotMaguni corpse linger so the client can play the die clip. */
        constexpr float kDieRemoveSec = 2.5f;

        void stop_monster_combat(MonsterEntity& m) {
            m.aggro = false;
            m.aggro_player_id = 0;
            m.moving = false;
            m.move_busy_left = 0.0f;
            m.idle_left = 0.0f;
            m.ai = MonsterEntity::Ai::Roam;
            m.attack_cooldown = 0.0f;
        }

        void begin_combat_corpse(MonsterEntity& m) {
            const auto target_hostility = m.hostility_by_player.find(m.aggro_player_id);
            const bool has_active_reward_hostility =
                m.aggro && m.aggro_player_id != 0 &&
                target_hostility != m.hostility_by_player.end() && target_hostility->second > 0;
            if (!has_active_reward_hostility) {
                m.hostility_by_player.clear();
                m.reward_damage_by_player.clear();
                m.aggro_hostility = 0;
            }
            m.hp = 0;
            stop_monster_combat(m);
            if (m.race == static_cast<int>(protocol::MonsterRace::Maguni)) {
                m.gstate |= protocol::kCgsKnee;
                m.knee_left = kMaguniKneeSec;
                m.die_remove_left = 0.0f;
            } else {
                m.gstate &= ~protocol::kCgsKnee;
                m.knee_left = 0.0f;
                m.die_remove_left = kDieRemoveSec;
            }
        }

        void broadcast_known_monster(std::vector<ClientSession>& clients,
                                     std::uint32_t id,
                                     const std::vector<std::uint8_t>& pkt) {
            for (auto& peer : clients) {
                if (peer.phase == SessionPhase::Playing && peer.sock &&
                    peer.known_monsters.find(id) != peer.known_monsters.end()) {
                    peer.sock->enqueue(pkt);
                }
            }
        }

        void erase_monster_and_notify(GameWorld& world,
                                      std::vector<ClientSession>& clients,
                                      std::uint32_t id) {
            const auto rem = frame_remove_monster(id);
            for (auto& peer : clients) {
                if (peer.phase == SessionPhase::Playing && peer.sock &&
                    peer.known_monsters.erase(id) > 0) {
                    peer.sock->enqueue(rem);
                }
            }
            auto& mons = world.monsters();
            mons.erase(std::remove_if(mons.begin(),
                                      mons.end(),
                                      [id](const MonsterEntity& m) { return m.id == id; }),
                       mons.end());
        }

        void select_collection_profile(ClientSession& c, bool pve) {
            const auto now = steady_ms_now();
            if (!pve) {
                c.collection_pvp_until_ms = now + 30000;
            }
            pve = pve && now >= c.collection_pvp_until_ms;
            if (pve == c.collection_pve || !c.collection_world) {
                return;
            }
            const auto hp = c.cur_hp;
            const auto mp = c.cur_mp;
            const auto max_hp = std::max(1, c.max_hp);
            const auto max_mp = std::max(1, c.max_mp);
            c.collection_pve = pve;
            recompute_combat(c, *c.collection_world);
            // Preserve resource fractions; changing profiles must never heal or grant mana.
            c.cur_hp = std::min(c.max_hp,
                                std::max(hp > 0 ? 1 : 0,
                                         combat::clamp_nonneg_i32(static_cast<std::int64_t>(hp) *
                                                                  c.max_hp / max_hp)));
            c.cur_mp = std::min(
                c.max_mp,
                combat::clamp_nonneg_i32(static_cast<std::int64_t>(mp) * c.max_mp / max_mp));
            if (c.sock) {
                send_progression_snapshot(c);
            }
        }

        /** Projects live or preview-derived values without changing the source session. */
        template <typename Derived>
        combat::Combatant make_session_combatant(const ClientSession& c, const Derived& stats) {
            combat::Combatant a;
            const int refining = c.skill_buffs.refining_weapon_points();
            a.level = c.level;
            a.min_attack = stats.min_attack + refining;
            a.max_attack = stats.max_attack + refining;
            a.min_magic = stats.min_magic + refining;
            a.max_magic = stats.max_magic + refining;
            a.armor_broken = c.skill_buffs.find(SkillBuffId::ThiefArmorBreaker) != nullptr;
            if (const auto* intensification =
                    c.skill_buffs.find(SkillBuffId::MageMagicIntensification)) {
                a.magic_intensification_rank = intensification->value1;
            }
            a.hit = stats.hit + c.skill_buffs.concentration_hit();
            a.dodge = stats.dodge;
            a.defense = stats.defense + c.skill_buffs.stone_defense();
            a.defense_range = stats.defense_range;
            a.absorb = stats.absorb + c.skill_buffs.stone_absorb();
            a.fatal_rate = stats.fatal_rate;
            a.fatal_pt = stats.fatal_pt;
            a.critical_damage_percent = stats.collection_bonus.ability[16];
            a.explosive_damage_percent = stats.collection_bonus.ability[17];
            a.talent_explosive_damage_percent =
                protocol::talent_bonuses(c.talent_mask).explosive_percent;
            a.perfect_evasion_base = stats.perfect_evasion_base;
            a.perfect_evasion_advanced = stats.perfect_evasion_advanced;
            a.block_percent = stats.block_percent;
            a.wearing_shield = stats.wearing_shield;
            a.wearing_two_hand = stats.wearing_two_hand;
            a.has_parry = learned_skill_level(c, combat::kKnightParrySkill) > 0;
            a.has_second_job_attrib =
                (static_cast<unsigned>(c.specialty) & combat::kSecondJobAttrib1) != 0;
            a.res_fire = stats.res_fire;
            a.res_ice = stats.res_ice;
            a.res_lightning = stats.res_lightning;
            a.res_curse = stats.res_curse;
            a.res_palsy = stats.res_palsy;
            a.attack_range = stats.attack_range;
            a.attack_speed_ms = stats.attack_speed_ms;
            a.is_player = true;
            a.clazz = c.clazz;
            a.attack_type = combat::player_attack_type(c.clazz);
            a.upgrade_level = stats.upgrade_level;
            a.char_attack = stats.char_attack;
            a.char_magic = stats.char_magic;
            a.weapon_min_attack = stats.weapon_min_attack + refining;
            a.weapon_max_attack = stats.weapon_max_attack + refining;
            a.weapon_min_magic = stats.weapon_min_magic + refining;
            a.weapon_max_magic = stats.weapon_max_magic + refining;
            a.bstate = c.pay_buffs.bstate() | c.skill_buffs.bstate();
            return a;
        }

        combat::Combatant
        session_combatant(ClientSession& c, bool pve = false, bool contact = true) {
            if (!contact && !pve && c.collection_pve && c.collection_world) {
                const auto preview =
                    calculate_combat(capture_combat_inputs(c, *c.collection_world, false));
                return make_session_combatant(c, preview);
            }
            if (contact) {
                select_collection_profile(c, pve);
            }
            return make_session_combatant(c, c);
        }

        combat::Combatant dummy_combatant(const DummyPlayer& dummy) {
            combat::Combatant a;
            a.level = dummy.level();
            a.min_attack = 1;
            a.max_attack = 1;
            a.is_player = true;
            a.clazz = dummy.clazz();
            a.attack_type = combat::player_attack_type(dummy.clazz());
            a.attack_range = 16;
            return a;
        }

        combat::Combatant monster_combatant(const MonsterEntity& m, const MonsterDef* def) {
            combat::Combatant t;
            t.level = def ? def->level : 1;
            t.min_attack = def ? def->min_attack : 1;
            t.max_attack = def ? def->max_attack : 1;
            t.hit = def ? def->hit : 0;
            t.dodge = def ? def->dodge : 0;
            t.defense = def ? def->defense_melee : 0;
            t.defense_range = def ? def->defense_range : 0;
            t.absorb = def ? def->absorb : 0;
            t.armor_broken = m.skill_buffs.find(SkillBuffId::ThiefArmorBreaker) != nullptr;
            t.res_fire = def ? def->res_fire : 0;
            t.res_ice = def ? def->res_ice : 0;
            t.res_lightning = def ? def->res_lightning : 0;
            t.res_curse = def ? def->res_curse : 0;
            t.res_palsy = def ? def->res_palsy : 0;
            if (m.doggebi_absorb_left > 0.0f) {
                t.absorb = combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.absorb) + 50);
            }
            if (m.doggebi_resist_all_left > 0.0f) {
                t.res_fire = combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.res_fire) + 50);
                t.res_ice = combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.res_ice) + 50);
                t.res_lightning =
                    combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.res_lightning) + 50);
                t.res_curse = combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.res_curse) + 50);
                t.res_palsy = combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.res_palsy) + 50);
            }
            t.attack_range = m.attack_range + static_cast<int>(m.skill_buffs.archer_range_delta());
            t.attack_speed_ms = combat::revised_attack_delay_ms(
                def ? def->attack_speed_ms : 2000, m.skill_buffs.archer_attack_speed_percent());
            t.attack_type = def ? def->attack_type : 0;
            const std::int32_t hit_percent = m.skill_buffs.archer_hit_percent();
            if (hit_percent != 0) {
                t.hit =
                    combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.hit) +
                                             static_cast<std::int64_t>(t.hit) * hit_percent / 100);
            }
            std::int32_t curse_v1 = 0;
            std::int32_t curse_v2 = 0;
            if (m.skill_buffs.values(SkillBuffId::ArcherCurseDefense, curse_v1, curse_v2)) {
                t.defense =
                    combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.defense) +
                                             static_cast<std::int64_t>(t.defense) * curse_v1 / 100);
                t.defense_range = combat::clamp_nonneg_i32(
                    static_cast<std::int64_t>(t.defense_range) +
                    static_cast<std::int64_t>(t.defense_range) * curse_v2 / 100);
            }
            if (m.skill_buffs.values(SkillBuffId::ArcherCurseStrength, curse_v1, curse_v2)) {
                t.min_attack = combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.min_attack) +
                                                        static_cast<std::int64_t>(t.min_attack) *
                                                            curse_v1 / 100);
                t.max_attack = combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.max_attack) +
                                                        static_cast<std::int64_t>(t.max_attack) *
                                                            curse_v1 / 100);
            }
            if (m.skill_buffs.values(SkillBuffId::ArcherCurseAgility, curse_v1, curse_v2)) {
                t.hit = combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.hit) +
                                                 static_cast<std::int64_t>(t.hit) * curse_v1 / 100);
                t.dodge =
                    combat::clamp_nonneg_i32(static_cast<std::int64_t>(t.dodge) +
                                             static_cast<std::int64_t>(t.dodge) * curse_v1 / 100);
            }
            return t;
        }

        [[nodiscard]] std::uint8_t pack_attack_flags(const combat::AttackResult& r) {
            std::uint8_t flags = 0;
            if (r.hit) {
                flags |= protocol::kAtkHit;
            }
            if (r.fatal) {
                flags |= protocol::kAtkFatal;
            }
            if (r.explosive) {
                flags |= protocol::kAtkExplosive;
            }
            if (r.blocked) {
                flags |= protocol::kAtkBlock;
            }
            return flags;
        }

        void apply_ice_slow_from_result(GameWorld& world,
                                        std::uint32_t monster_id,
                                        const combat::AttackResult& result,
                                        std::vector<ClientSession>& clients) {
            if (result.ice_slow_duration_sec <= 0) {
                return;
            }
            if (!world.apply_monster_slow(monster_id,
                                          static_cast<float>(result.ice_slow_duration_sec),
                                          result.ice_slow_percent)) {
                return;
            }
            MonsterEntity* monster = world.find_monster(monster_id);
            if (!monster) {
                return;
            }
            monster->dirty_slow = false;
            const bool ice_slow = monster->slow_left > 0.0f && monster->slow_percent < 0;
            const int dark = monster->skill_buffs.archer_move_speed_percent();
            const bool slow = ice_slow || dark < 0;
            std::uint64_t mstate = 0;
            if (slow) {
                mstate |= protocol::kCmsMoveSpeed;
            }
            if (monster->control_left > 0.0f) {
                mstate |= protocol::kCmsMoveStop;
            }
            std::int32_t speed_pct = ice_slow ? monster->slow_percent : 0;
            if (dark < 0) {
                speed_pct = (speed_pct == 0) ? dark : std::min(speed_pct, dark);
            }
            const std::int16_t speed = slow ? static_cast<std::int16_t>(speed_pct) : 0;
            broadcast_known_monster(
                clients, monster->id, protocol::MState::frame(monster->id, mstate));
            broadcast_known_monster(clients,
                                    monster->id,
                                    protocol::Property::frame_update_mproperty(
                                        monster->id, protocol::kPropertyMSpeed, speed));
        }

        void maybe_ice_mastery_slow(combat::AttackResult& result,
                                    int skill_index,
                                    int owner_level,
                                    int target_level,
                                    int ice_mastery) {
            if (combat::mage_skill_resist(skill_index) != combat::MagicResist::Ice) {
                return;
            }
            combat::apply_ice_mastery_slow(result, owner_level, target_level, ice_mastery);
        }

        void apply_storm_palsy(combat::AttackResult& result,
                               const combat::Combatant& owner,
                               const combat::Combatant& target) {
            result.palsy = combat::get_palsy_extra(owner, target);
            if (result.palsy > 0) {
                result.explosive = true;
                result.damage = combat::clamp_nonneg_i32(static_cast<std::int64_t>(result.damage) +
                                                         result.palsy);
            }
        }

        /** One bag cell created or grown by an insert. */
        struct BagInsert {
            std::uint32_t iid = 0;
            int added = 0;
            bool merged = false;
        };

        /** @return True when stacking is enabled and the item is not wearable. */
        [[nodiscard]] bool item_is_stackable(const GameWorld& world, int item_index) {
            const auto& items = world.item_defs();
            const auto it = items.find(item_index);
            if (it == items.end()) {
                return false;
            }
            return it->second.stackable && !it->second.wearable;
        }

        /** @return True when item definition class is quest (compatibility behavior is false). */
        [[nodiscard]] bool item_is_quest(const GameWorld& world, int item_index) {
            const auto& items = world.item_defs();
            const auto it = items.find(item_index);
            if (it == items.end()) {
                return false;
            }
            return it->second.class_big == "quest";
        }

        /** Resolves the dedicated writable range; login restores all General cells.
         * @param c Session with active General expansions.
         * @param world Public item definitions used to classify the item.
         * @param index Item definition index.
         * @param restore True to include expired General cells during login.
         * @return Half-open storage range for General, Quest Items or Task Items.
         */
        [[nodiscard]] std::pair<int, int> bag_slot_range(const ClientSession& c,
                                                         const GameWorld& world,
                                                         int index,
                                                         bool restore = false) {
            const auto* def = item_def_of(world, index);
            if (def && def->class_big == "quest") {
                const int base = ClientSession::kGeneralSlots +
                                 (def->is_task ? ClientSession::kSlotsPerRegister : 0);
                return {base, base + ClientSession::kSlotsPerRegister};
            }
            return {0, restore ? ClientSession::kGeneralSlots : unlocked_bag_slot_count(c)};
        }

        /** @return True when item definition pay / cash-shop flag is set (compatibility behavior).
         */
        [[nodiscard]] bool item_is_pay(const GameWorld& world, int item_index) {
            const auto& items = world.item_defs();
            const auto it = items.find(item_index);
            if (it == items.end()) {
                return false;
            }
            return it->second.pay;
        }

        [[nodiscard]] ClientSession::BagSlot* find_bag_slot(ClientSession& c, std::uint32_t iid) {
            if (iid == 0) {
                return nullptr;
            }
            for (auto& slot : c.bag) {
                if (slot.iid == iid) {
                    return &slot;
                }
            }
            return nullptr;
        }

        [[nodiscard]] std::uint8_t clamp_u8(int value) {
            return static_cast<std::uint8_t>(std::clamp(value, 0, 255));
        }

        [[nodiscard]] protocol::InsertCharmFields
        charm_fields_of(const ClientSession::BagSlot& slot) {
            protocol::InsertCharmFields fields;
            fields.x_attack = clamp_u8(slot.x_attack);
            fields.x_magic = clamp_u8(slot.x_magic);
            fields.x_hit = clamp_u8(slot.x_hit);
            fields.x_defense = clamp_u8(slot.x_defense);
            fields.x_dodge = clamp_u8(slot.x_dodge);
            fields.upgrade_level = clamp_u8(slot.upgrade_level);
            fields.upgrade_rate = clamp_u8(slot.upgrade_rate);
            fields.mix_type = clamp_u8(slot.mix_type);
            fields.bof = clamp_u8(slot.bof);
            fields.qigong_perforated = clamp_u8(slot.qigong_perforated);
            fields.qigong_effect = clamp_u8(slot.qigong_effect);
            fields.dragon_effect = clamp_u8(slot.dragon_effect);
            fields.random_stat_type = clamp_u8(slot.random_stat_type);
            fields.random_stat_value = clamp_u8(slot.random_stat_value);
            return fields;
        }

        [[nodiscard]] std::uint64_t item_expire_at(const ClientSession::BagSlot& slot) {
            return static_cast<std::uint64_t>(
                std::max<std::int64_t>({0, slot.pet_expire_at, slot.ride_expire_at}));
        }

        [[nodiscard]] protocol::StorageItem storage_item_of(const ItemRecord& item) {
            protocol::StorageItem out;
            out.iid = static_cast<std::uint32_t>(std::max(0, item.iid));
            out.index = static_cast<std::uint16_t>(std::clamp(item.index, 0, 65535));
            out.prefix = clamp_u8(item.prefix);
            out.slot = static_cast<std::uint16_t>(
                std::clamp(item.slot, 0, protocol::kStorageCapacity - 1));
            out.count = static_cast<std::uint32_t>(std::max(0, item.count));
            out.info = protocol::pack_insert_info(true,
                                                  item.cur_end,
                                                  item.max_end,
                                                  false,
                                                  item.account_bound,
                                                  item.enchant_protected,
                                                  item.character_bound);
            out.charm.x_attack = clamp_u8(item.x_attack);
            out.charm.x_magic = clamp_u8(item.x_magic);
            out.charm.x_hit = clamp_u8(item.x_hit);
            out.charm.x_defense = clamp_u8(item.x_defense);
            out.charm.x_dodge = clamp_u8(item.x_dodge);
            out.charm.upgrade_level = clamp_u8(item.upgrade_level);
            out.charm.upgrade_rate = clamp_u8(item.upgrade_rate);
            out.charm.mix_type = clamp_u8(item.mix_type);
            out.charm.bof = clamp_u8(item.bof);
            out.charm.qigong_perforated = clamp_u8(item.qigong_perforated);
            out.charm.qigong_effect = clamp_u8(item.qigong_effect);
            out.charm.dragon_effect = clamp_u8(item.dragon_effect);
            out.charm.random_stat_type = clamp_u8(item.random_stat_type);
            out.charm.random_stat_value = clamp_u8(item.random_stat_value);
            out.transform_level =
                static_cast<std::uint16_t>(std::clamp(item.transform_level, 1, 65535));
            out.transform_exp = static_cast<std::uint32_t>(std::max(0, item.transform_exp));
            return out;
        }

        [[nodiscard]] ClientSession::BagSlot bag_slot_of(const ItemRecord& item) {
            ClientSession::BagSlot slot;
            slot.iid = static_cast<std::uint32_t>(std::max(0, item.iid));
            slot.index = item.index;
            slot.prefix = item.prefix;
            slot.count = item.count;
            slot.cur_end = item.cur_end;
            slot.max_end = item.max_end;
            slot.x_attack = item.x_attack;
            slot.x_magic = item.x_magic;
            slot.x_hit = item.x_hit;
            slot.x_defense = item.x_defense;
            slot.x_dodge = item.x_dodge;
            slot.upgrade_level = item.upgrade_level;
            slot.upgrade_rate = item.upgrade_rate;
            slot.mix_type = item.mix_type;
            slot.bof = item.bof;
            slot.qigong_perforated = item.qigong_perforated;
            slot.qigong_effect = item.qigong_effect;
            slot.dragon_effect = item.dragon_effect;
            slot.random_stat_type = item.random_stat_type;
            slot.random_stat_value = item.random_stat_value;
            slot.transform_level = item.transform_level;
            slot.transform_exp = item.transform_exp;
            slot.pet_expire_at = item.pet_expire_at;
            slot.ride_expire_at = item.ride_expire_at;
            slot.account_bound = item.account_bound;
            slot.character_bound = item.character_bound;
            slot.enchant_protected = item.enchant_protected;
            return slot;
        }

        void send_storage_info(IDataStore* store, ClientSession& c) {
            if (!store || !c.sock || c.account_id <= 0 || c.active_storage_npc_id == 0) {
                return;
            }
            protocol::StorageInfo info;
            info.npc_id = c.active_storage_npc_id;
            for (const ItemRecord& item : store->load_storage_items(c.account_id)) {
                if (item.iid <= 0 || item.index <= 0 || item.count <= 0 || item.slot < 0 ||
                    item.slot >= protocol::kStorageCapacity) {
                    continue;
                }
                info.items.push_back(storage_item_of(item));
            }
            c.sock->enqueue(protocol::Storage::frame_info_s2c(info));
        }

        /** Sends the durable system-mail inbox for the active character. */
        void send_system_mail_list(IDataStore* store, ClientSession& c) {
            if (!store || !c.sock || c.character_id <= 0) {
                return;
            }
            std::vector<protocol::MailEntry> entries;
            for (const SystemMailRecord& mail : store->list_system_mail(c.character_id)) {
                if (mail.id <= 0 ||
                    mail.id >
                        static_cast<std::int64_t>(std::numeric_limits<std::uint32_t>::max()) ||
                    mail.item_index < 0 ||
                    mail.item_index > std::numeric_limits<std::uint16_t>::max() ||
                    mail.item_count < 0 || ((mail.item_index == 0) != (mail.item_count == 0))) {
                    continue;
                }
                protocol::MailEntry entry;
                entry.id = static_cast<std::uint32_t>(mail.id);
                entry.item_index = static_cast<std::uint16_t>(mail.item_index);
                entry.item_count = static_cast<std::uint32_t>(mail.item_count);
                entry.created_at =
                    static_cast<std::uint64_t>(std::max<std::int64_t>(0, mail.created_at));
                entry.claimed = mail.claimed_at != 0;
                entry.read = mail.read_at != 0;
                entry.subject = mail.subject;
                entry.body = mail.body;
                entries.push_back(std::move(entry));
            }
            c.sock->enqueue(protocol::Mail::frame_list_s2c(entries));
        }

        [[nodiscard]] CharmState charm_state_of(const ClientSession::BagSlot& slot) {
            CharmState state;
            state.x_attack = slot.x_attack;
            state.x_magic = slot.x_magic;
            state.x_hit = slot.x_hit;
            state.x_defense = slot.x_defense;
            state.x_dodge = slot.x_dodge;
            state.upgrade_level = slot.upgrade_level;
            state.upgrade_rate = slot.upgrade_rate;
            state.cur_end = slot.cur_end;
            state.max_end = slot.max_end;
            state.enchant_protected = slot.enchant_protected;
            return state;
        }

