            slot.x_attack = state.x_attack;
            slot.x_magic = state.x_magic;
            slot.x_hit = state.x_hit;
            slot.x_defense = state.x_defense;
            slot.x_dodge = state.x_dodge;
            slot.upgrade_level = state.upgrade_level;
