        chat_service.commands().register_command("spawn", [&](const ChatCommandContext& ctx) {
            if (chat_sender == nullptr) {
                return ChatCommandResult(false, "Spawn failed.");
            }
            const std::string args = ascii_lower_args(ctx.args());
            int monster_index = 0;
            char trailing = '\0';
            if (std::sscanf(args.c_str(), "monster %d %c", &monster_index, &trailing) != 1 ||
                monster_index <= 0) {
                return ChatCommandResult("Usage: /spawn monster <index>");
            }
            std::string monster_name;
            {
                std::lock_guard<std::mutex> lock(m_world_mutex);
                if (monster_index == kDoggebiLordMonsterIndex && doggebi.lord_id != 0 &&
                    m_world.find_monster(doggebi.lord_id) != nullptr) {
                    return ChatCommandResult(false, "The Doggebi Lord is already active.");
                }
                const auto spawned_id = m_world.spawn_monster_at(m_next_entity_id,
                                                                 monster_index,
                                                                 chat_sender->map,
                                                                 chat_sender->px,
                                                                 chat_sender->py,
                                                                 chat_sender->pz);
                if (!spawned_id.has_value()) {
                    return ChatCommandResult(false,
                                             "Spawn failed: unknown monster or blocked location.");
                }
                MonsterEntity* spawned = m_world.find_monster(*spawned_id);
                if (spawned == nullptr) {
                    return ChatCommandResult(false, "Spawn failed.");
                }
                monster_name = spawned->name;
                if (monster_index == kDoggebiLordMonsterIndex) {
                    // The test path must exercise the same combat controller as the ritual.
                    spawned->aggressive = true;
                    doggebi.lord_id = *spawned_id;
                    doggebi.lord_despawn_ms = steady_ms_now() + kDoggebiLordLifetimeMs;
                    doggebi.spirit_ids.clear();
                    doggebi.spirit_max = 0;
                    doggebi.spawn_cursor = 0;
                    reset_doggebi_skill_controller(doggebi);
                }
            }
            return ChatCommandResult("Spawned " + monster_name + " (" +
                                     std::to_string(monster_index) + ").");
        });
        chat_service.commands().register_command("teleport", [&](const ChatCommandContext& ctx) {
            if (chat_sender == nullptr) {
                return ChatCommandResult(false, "Teleport failed.");
            }
            if (is_assassin(*chat_sender)) {
                return ChatCommandResult(false,
                                         "You cannot teleport while wearing the Assassin Mask.");
            }
            int dungeon = 0;
            int area = 0;
            if (map::PortalCatalog::parse_dungeon_arg(ctx.args(), dungeon)) {
                const map::PortalRecord* portal = m_portals.entrance_for_dungeon(dungeon);
                if (portal == nullptr) {
                    return ChatCommandResult(false, "Teleport failed.");
                }
                begin_session_teleport(*chat_sender,
                                       0,
                                       portal->entrance_x(),
                                       portal->entrance_y(),
                                       portal->entrance_z());
                return ChatCommandResult("Teleporting to D" + std::to_string(dungeon) + " portal.");
            }
            std::string place_id;
            if (map::PortalCatalog::parse_place_arg(ctx.args(), place_id)) {
                const map::PortalRecord* portal = m_portals.find_by_id(place_id);
                if (portal == nullptr) {
                    return ChatCommandResult(false, "Teleport failed.");
                }
                begin_session_teleport(
                    *chat_sender, portal->to_map(), portal->to_x(), portal->to_y(), portal->to_z());
                return ChatCommandResult(map::PortalCatalog::place_teleport_reply(place_id));
            }
            if (!map::PortalCatalog::parse_area_arg(ctx.args(), area)) {
                return ChatCommandResult(std::string(map::kTeleportUsage));
            }
            MonsterSpawn spawn;
            {
                std::lock_guard<std::mutex> lock(m_world_mutex);
                const MonsterSpawn* found = m_world.find_spawn_by_area(area);
                if (found == nullptr) {
                    return ChatCommandResult(false, "Unknown monster area.");
                }
                spawn = *found;
            }
            const int x = (spawn.x0 + spawn.x1) / 2;
            const int y = (spawn.y0 + spawn.y1) / 2;
            bool walkable = false;
            {
                std::lock_guard<std::mutex> lock(m_world_mutex);
                walkable = m_world.ensure_cell_for_pixel(x, y) && m_world.walkable_pixel(x, y);
            }
            if (!walkable) {
                return ChatCommandResult(false, "Cannot teleport: no walkable map at that area.");
            }
            begin_session_teleport(*chat_sender, spawn.map_index, x, y, m_config.spawn_z);
            return ChatCommandResult("Teleporting to monster area " + std::to_string(area) +
                                     " (map " + std::to_string(spawn.map_index) + ").");
        });
