        chat_service.commands().register_command("level", [&](const ChatCommandContext& ctx) {
            if (chat_sender == nullptr) {
                return ChatCommandResult(false, "Level change failed.");
            }
            protocol::LevelUpArgs parsed;
            if (!protocol::LevelUp::parse_args(ctx.args(), parsed)) {
                return ChatCommandResult(std::string(protocol::kLevelUsage));
            }
            if (parsed.op == protocol::LevelOp::Add) {
                if (chat_sender->level >= protocol::kMaxPlayerLevel) {
                    return ChatCommandResult("Already at maximum level.");
                }
                // initial /levelup GM command zeros EXP, then UpdateProperty(P_LEVEL, add, 1).
                chat_sender->exp = 0;
                int granted = 0;
                while (granted < parsed.value && chat_sender->level < protocol::kMaxPlayerLevel) {
                    apply_level_up(
                        *chat_sender, clients, m_world, m_store.get(), &m_level_mail_rewards);
                    ++granted;
                }
                if (chat_sender->sock) {
                    chat_sender->sock->enqueue(
                        protocol::Property::frame_update_exp(chat_sender->exp, 0));
                }
                persist_character(m_store.get(), *chat_sender);
                return ChatCommandResult("Leveled up to " + std::to_string(chat_sender->level) +
                                         ".");
            }
            if (parsed.op == protocol::LevelOp::Subtract) {
                if (chat_sender->level <= 1) {
                    return ChatCommandResult("Already at minimum level.");
                }
                const int target = std::max(1, chat_sender->level - parsed.value);
                apply_level_rebuild(*chat_sender, clients, m_world, m_store.get(), target);
                return ChatCommandResult("Level set to " + std::to_string(chat_sender->level) +
                                         ".");
            }
            const int target = std::clamp(parsed.value, 1, protocol::kMaxPlayerLevel);
            apply_level_rebuild(*chat_sender, clients, m_world, m_store.get(), target);
            return ChatCommandResult("Level set to " + std::to_string(chat_sender->level) + ".");
        });
