            std::int64_t delta = 0;
            if (parsed.op == protocol::ChatAmountOp::Add) {
                delta = parsed.value;
            } else if (parsed.op == protocol::ChatAmountOp::Subtract) {
                delta = chat_sender->exp - before;
            }
            consume_player_exp(
                *chat_sender, clients, m_world, m_store.get(), &m_level_mail_rewards);
            if (chat_sender->sock) {
                chat_sender->sock->enqueue(
                    protocol::Property::frame_update_exp(chat_sender->exp, delta));
            }
            persist_character(m_store.get(), *chat_sender);
            send_progression_snapshot(*chat_sender);
